import { createRoute, z } from '@hono/zod-openapi'

const FallbackAssemblyAITranscriberSchema = z
  .object({
    provider: z
      .literal('assembly-ai')
      .openapi({ description: 'This is the transcription provider that will be used.' }),
    language: z
      .enum(['multi', 'en'])
      .exactOptional()
      .openapi({ description: 'This is the language that will be set for the transcription.' }),
    confidenceThreshold: z
      .number()
      .min(0)
      .max(1)
      .exactOptional()
      .openapi({
        description:
          'Transcripts below this confidence threshold will be discarded.\n\n@default 0.4',
        example: 0.4,
      }),
    formatTurns: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'This enables formatting of transcripts.\n\n@default true',
        example: true,
      }),
    endOfTurnConfidenceThreshold: z
      .number()
      .min(0)
      .max(1)
      .exactOptional()
      .openapi({
        description:
          'This is the end of turn confidence threshold. The minimum confidence that the end of turn is detected.\nNote: Only used if startSpeakingPlan.smartEndpointingPlan is not set.\n@min 0\n@max 1\n@default 0.7',
        example: 0.7,
      }),
    minEndOfTurnSilenceWhenConfident: z
      .number()
      .min(0)
      .exactOptional()
      .openapi({
        description:
          'This is the minimum end of turn silence when confident in milliseconds.\nNote: Only used if startSpeakingPlan.smartEndpointingPlan is not set.\n@default 160',
        example: 160,
      }),
    wordFinalizationMaxWaitTime: z
      .number()
      .min(0)
      .exactOptional()
      .openapi({ deprecated: true, example: 160 }),
    maxTurnSilence: z
      .number()
      .min(0)
      .exactOptional()
      .openapi({
        description:
          'This is the maximum turn silence time in milliseconds.\nNote: Only used if startSpeakingPlan.smartEndpointingPlan is not set.\n@default 400',
        example: 400,
      }),
    vadAssistedEndpointingEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Use VAD to assist with endpointing decisions from the transcriber.\nWhen enabled, transcriber endpointing will be buffered if VAD detects the user is still speaking, preventing premature turn-taking.\nWhen disabled, transcriber endpointing will be used immediately regardless of VAD state, allowing for quicker but more aggressive turn-taking.\nNote: Only used if startSpeakingPlan.smartEndpointingPlan is not set.\n\n@default true',
        example: true,
      }),
    mode: z
      .enum(['max_accuracy', 'min_latency', 'balanced'])
      .exactOptional()
      .openapi({
        description:
          "This is the transcription mode used by the Universal Pro speech models. Only applies to `universal-3-5-pro` and `universal-3-6-pro`.\n\n@default 'balanced'",
      }),
    prompt: z
      .string()
      .max(1750)
      .exactOptional()
      .openapi({
        description:
          'This is a prompt that provides additional context to the transcription model. Only applies to `universal-3-5-pro` and `universal-3-6-pro`.',
      }),
    agentContext: z
      .string()
      .max(1750)
      .exactOptional()
      .openapi({
        description:
          'This is context about the voice agent that guides the transcription model. Only applies to `universal-3-5-pro` and `universal-3-6-pro`.',
      }),
    agentContextAutoUpdateEnabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "When true, the text the assistant just spoke is sent to AssemblyAI as `agent_context` after every assistant turn, replacing the previous value, so the user's reply is transcribed in the context of the question it answers.\n`agentContext` still seeds the first turn. Text longer than 1750 characters keeps its last 1750 characters. Turns the user interrupted are not sent when the interruption is detected by voice activity (the default, `stopSpeakingPlan.numWords: 0`).\nOnly applies to `universal-3-5-pro` and `universal-3-6-pro`.\n\n@default false",
      }),
    languageCodes: z
      .array(
        z.enum([
          'en',
          'es',
          'fr',
          'de',
          'it',
          'pt',
          'tr',
          'nl',
          'sv',
          'no',
          'da',
          'fi',
          'hi',
          'vi',
          'ar',
          'he',
          'ja',
          'zh',
          'ur',
          'ru',
          'ko',
          'ca',
          'gl',
          'ro',
          'et',
          'fa',
          'yue',
          'af',
          'mr',
          'zu',
          'xh',
          'nn',
        ]),
      )
      .exactOptional()
      .openapi({
        description:
          'These are language codes used to steer automatic language detection. Only applies to `universal-3-5-pro` and `universal-3-6-pro`.\n`ur`, `ru`, `ko`, `ca`, `gl`, `ro`, `et`, `fa`, `yue`, `af`, `mr`, `zu`, `xh` and `nn` were added with `universal-3-6-pro`.',
      }),
    speechModel: z
      .enum([
        'universal-streaming-english',
        'universal-streaming-multilingual',
        'universal-3-5-pro',
        'universal-3-6-pro',
      ])
      .exactOptional()
      .openapi({
        description:
          "This is the speech model used for the streaming session.\nKeyterms prompting is supported on universal-streaming-english, universal-3-5-pro and universal-3-6-pro.\nuniversal-3-6-pro is AssemblyAI's newest and most accurate voice-agent model.\n@default 'universal-streaming-english'",
      }),
    realtimeUrl: z
      .string()
      .exactOptional()
      .openapi({ description: 'The WebSocket URL that the transcriber connects to.' }),
    wordBoost: z
      .array(z.string().max(2500))
      .exactOptional()
      .openapi({ description: 'Add up to 2500 characters of custom vocabulary.' }),
    keytermsPrompt: z
      .array(z.string().max(50))
      .exactOptional()
      .openapi({
        description:
          'Keyterms prompting improves recognition accuracy for specific words and phrases.\nCan include up to 100 keyterms, each up to 50 characters.\nCosts an additional $0.04/hour on universal-streaming-english and is included at no extra cost on the Universal Pro models (universal-3-5-pro, universal-3-6-pro).',
      }),
    endUtteranceSilenceThreshold: z
      .number()
      .exactOptional()
      .openapi({
        description: 'The duration of the end utterance silence threshold in milliseconds.',
      }),
    disablePartialTranscripts: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Disable partial transcripts.\nSet to `true` to not receive partial transcripts. Defaults to `false`.',
      }),
  })
  .openapi({ required: ['provider'] })
  .openapi('FallbackAssemblyAITranscriber')

