const ConditionSchema = z
  .object({
    operator: z
      .enum(['eq', 'neq', 'gt', 'gte', 'lt', 'lte'])
      .openapi({
        description: 'This is the operator you want to use to compare the parameter and value.',
      }),
    param: z
      .string()
      .max(1000)
      .openapi({ description: 'This is the name of the parameter that you want to check.' }),
    value: z
      .string()
      .max(1000)
      .openapi({ description: 'This is the value you want to compare against the parameter.' }),
  })
  .openapi({ required: ['operator', 'param', 'value'] })
  .openapi('Condition')

