const MessageTargetSchema = z
  .object({
    role: z
      .enum(['user', 'assistant'])
      .exactOptional()
      .openapi({
        description:
          'This is the role of the message to target.\n\nIf not specified, will find the position in the message history ignoring role (effectively `any`).',
        example: 'user',
      }),
    position: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'This is the position of the message to target.\n- Negative numbers: Count from end (-1 = most recent, -2 = second most recent)\n- 0: First/oldest message in history\n- Positive numbers: Specific position (0-indexed from start)\n\n@default -1 (most recent message)',
        example: -1,
      }),
  })
  .openapi({ required: [] })
  .openapi('MessageTarget')

const RegexConditionSchema = z
  .object({
    type: z
      .literal('regex')
      .openapi({
        description: 'This is the type discriminator for regex condition',
        example: 'regex',
      }),
    regex: z
      .string()
      .openapi({
        description:
          'This is the regular expression pattern to match against message content.\n\nNote:\n- This works by using the RegExp.test method in Node.JS. Eg. /hello/.test("hello there") will return true.\n\nHot tips:\n- In JavaScript, escape \\ when sending the regex pattern. Eg. "hello\\sthere" will be sent over the wire as "hellosthere". Send "hello\\\\sthere" instead.\n- RegExp.test does substring matching, so /cat/.test("I love cats") will return true. To do full string matching, use anchors: /^cat$/ will only match exactly "cat".\n- Word boundaries \\b are useful for matching whole words: /\\bcat\\b/ matches "cat" but not "cats" or "category".\n- Use inline flags for portability: (?i) for case insensitive, (?m) for multiline',
        examples: [
          '\\\\b(cancel|stop|wait)\\\\b - Matches whole words',
          '^yes$ - Matches exactly yes (full string match)',
          '(?i)hello - Case insensitive match',
        ],
      }),
    target: MessageTargetSchema.exactOptional().openapi({
      description:
        'This is the target for messages to check against.\nIf not specified, the condition will run on the last message (position: -1).\nIf role is not specified, it will look at the last message regardless of role.\n@default { position: -1 }',
    }),
    negate: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This is the flag that when true, the condition matches if the pattern does NOT match.\nUseful for ensuring certain words/phrases are absent.\n\n@default false',
        example:
          'true - Reject if user hasn"t said goodbye: { regex: "\\\\b(bye|goodbye)\\\\b", negate: true }',
      }),
  })
  .openapi({ required: ['type', 'regex'] })
  .openapi('RegexCondition')

const LiquidConditionSchema = z
  .object({
    type: z
      .literal('liquid')
      .openapi({
        description: 'This is the type discriminator for liquid condition',
        example: 'liquid',
      }),
    liquid: z
      .string()
      .openapi({
        description:
          "This is the Liquid template that must return exactly \"true\" or \"false\" as a string.\nThe template is evaluated and the entire output must be either \"true\" or \"false\" - nothing else.\n\nAvailable variables:\n- `messages`: Array of recent messages in OpenAI chat completions format (ChatCompletionMessageParam[])\n  Each message has properties like: role ('user', 'assistant', 'system'), content (string), etc.\n- `now`: Current timestamp in milliseconds (built-in Liquid variable)\n- Any assistant variable values (e.g., `userName`, `accountStatus`)\n\nUseful Liquid filters for messages:\n- `messages | last: 5` - Get the 5 most recent messages\n- `messages | where: 'role', 'user'` - Filter to only user messages\n- `messages | reverse` - Reverse the order of messages",
        examples: [
          '{% if messages.last.content contains goodbye %}true{% else %}false{% endif %}',
          '{% assign userMessages = messages | where: role, user %}{% if userMessages.size > 3 %}true{% else %}false{% endif %}',
        ],
      }),
  })
  .openapi({ required: ['type', 'liquid'] })
  .openapi('LiquidCondition')

