const ContextEngineeringPlanAllSchema: z.ZodType<ContextEngineeringPlanAllType> = z
  .object({ type: z.literal('all') })
  .openapi({ required: ['type'] })
  .openapi('ContextEngineeringPlanAll')

const SummaryPlanSchema = z
  .object({
    messages: z
      .array(z.object({}))
      .exactOptional()
      .openapi({
        description:
          'These are the messages used to generate the summary.\n\n@default: ```\n[\n  {\n    "role": "system",\n    "content": "You are an expert note-taker. You will be given a transcript of a call. Summarize the call in 2-3 sentences. DO NOT return anything except the summary."\n  },\n  {\n    "role": "user",\n    "content": "Here is the transcript:\\n\\n{{transcript}}\\n\\n. Here is the ended reason of the call:\\n\\n{{endedReason}}\\n\\n"\n  }\n]```\n\nYou can customize by providing any messages you want.\n\nHere are the template variables available:\n- {{transcript}}: The transcript of the call from `call.artifact.transcript` \n- {{systemPrompt}}: The system prompt of the call from `assistant.model.messages[type=system].content` \n- {{messages}}: The messages of the call from `assistant.model.messages` \n- {{endedReason}}: The ended reason of the call from `call.endedReason`',
      }),
    enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether a summary is generated and stored in `call.analysis.summary`. Defaults to true.\n\nUsage:\n- If you want to disable the summary, set this to false.\n\n@default true',
      }),
    timeoutSeconds: z
      .number()
      .min(1)
      .max(60)
      .exactOptional()
      .openapi({
        description:
          'This is how long the request is tried before giving up. When request times out, `call.analysis.summary` will be empty.\n\nUsage:\n- To guarantee the summary is generated, set this value high. Note, this will delay the end of call report in cases where model is slow to respond.\n\n@default 5 seconds',
      }),
  })
  .openapi({ required: [] })
  .openapi('SummaryPlan')

const TransferFallbackPlanSchema = z
  .object({
    message: z
      .xor([z.string(), CustomMessageSchema])
      .openapi({
        description:
          'This is the message the assistant will deliver to the customer if the transfer fails.',
      }),
    endCallEnabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          "This controls what happens after delivering the failure message to the customer.\n- true: End the call after delivering the failure message (default)\n- false: Keep the assistant on the call to continue handling the customer's request\n\n@default true",
      }),
  })
  .openapi({ required: ['message'] })
  .openapi('TransferFallbackPlan')

const TransferPlanSchema = z
  .object({
    mode: z
      .enum([
        'blind-transfer',
        'blind-transfer-add-summary-to-sip-header',
        'warm-transfer-say-message',
        'warm-transfer-say-summary',
        'warm-transfer-twiml',
        'warm-transfer-wait-for-operator-to-speak-first-and-then-say-message',
        'warm-transfer-wait-for-operator-to-speak-first-and-then-say-summary',
        'warm-transfer-experimental',
      ])
      .openapi({
        description:
          "This configures how transfer is executed and the experience of the destination party receiving the call.\n\nUsage:\n- `blind-transfer`: The assistant forwards the call to the destination without any message or summary.\n- `blind-transfer-add-summary-to-sip-header`: The assistant forwards the call to the destination and adds a SIP header X-Transfer-Summary to the call to include the summary.\n- `warm-transfer-say-message`: The assistant dials the destination, delivers the `message` to the destination party, connects the customer, and leaves the call.\n- `warm-transfer-say-summary`: The assistant dials the destination, provides a summary of the call to the destination party, connects the customer, and leaves the call.\n- `warm-transfer-wait-for-operator-to-speak-first-and-then-say-message`: The assistant dials the destination, waits for the operator to speak, delivers the `message` to the destination party, and then connects the customer.\n- `warm-transfer-wait-for-operator-to-speak-first-and-then-say-summary`: The assistant dials the destination, waits for the operator to speak, provides a summary of the call to the destination party, and then connects the customer.\n- `warm-transfer-twiml`: The assistant dials the destination, executes the twiml instructions on the destination call leg, connects the customer, and leaves the call.\n- `warm-transfer-experimental`: The assistant puts the customer on hold, dials the destination, and if the destination answers (and is human), delivers a message or summary before connecting the customer. If the destination is unreachable or not human (e.g., with voicemail detection), the assistant delivers the `fallbackMessage` to the customer and optionally ends the call.\n\n@default 'blind-transfer'",
      }),
    message: z
      .xor([z.string(), CustomMessageSchema])
      .exactOptional()
      .openapi({
        description:
          'This is the message the assistant will deliver to the destination party before connecting the customer.\n\nUsage:\n- Used only when `mode` is `blind-transfer-add-summary-to-sip-header`, `warm-transfer-say-message`, `warm-transfer-wait-for-operator-to-speak-first-and-then-say-message`, or `warm-transfer-experimental`.',
      }),
    timeout: z
      .number()
      .min(1)
      .max(600)
      .default(60)
      .exactOptional()
      .openapi({
        description:
          'This is the timeout in seconds for the warm-transfer-wait-for-operator-to-speak-first-and-then-say-message/summary\n\n@default 60',
      }),
    sipVerb: z
      .enum(['refer', 'bye', 'dial'])
      .default('refer')
      .exactOptional()
      .openapi({
        description:
          "This specifies the SIP verb to use while transferring the call.\n- 'refer': Uses SIP REFER to transfer the call (default)\n- 'bye': Ends current call with SIP BYE\n- 'dial': Uses SIP DIAL to transfer the call",
      }),
    dialTimeout: z
      .number()
      .min(1)
      .max(600)
      .default(60)
      .exactOptional()
      .openapi({
        description:
          "This sets the timeout for the dial operation in seconds. This is the duration the call will ring before timing out.\n\nOnly applicable when `sipVerb='dial'`. Not applicable for SIP REFER or BYE.\n\n@default 60",
      }),
    holdAudioUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the URL to an audio file played while the customer is on hold during transfer.\n\nUsage:\n- Used only when `mode` is `warm-transfer-experimental`.\n- Used when transferring calls to play hold audio for the customer.\n- Must be a publicly accessible URL to an audio file.\n- Supported formats: MP3 and WAV.\n- If not provided, the default hold audio will be used.',
      }),
    transferCompleteAudioUrl: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is the URL to an audio file played after the warm transfer message or summary is delivered to the destination party.\nIt can be used to play a custom sound like 'beep' to notify that the transfer is complete.\n\nUsage:\n- Used only when `mode` is `warm-transfer-experimental`.\n- Used when transferring calls to play hold audio for the destination party.\n- Must be a publicly accessible URL to an audio file.\n- Supported formats: MP3 and WAV.",
      }),
    contextEngineeringPlan: z
      .xor([
        ContextEngineeringPlanLastNMessagesSchema.openapi({ title: 'Last N Messages' }),
        ContextEngineeringPlanNoneSchema.openapi({ title: 'None' }),
        ContextEngineeringPlanAllSchema.openapi({ title: 'All' }),
      ])
      .exactOptional()
      .openapi({
        description:
          "This is the plan for manipulating the message context before initiating the warm transfer.\nUsage:\n- Used only when `mode` is `warm-transfer-experimental`.\n- These messages will automatically be added to the transferAssistant's system message.\n- If 'none', we will not add any transcript to the transferAssistant's system message.\n- If you want to provide your own messages, use transferAssistant.model.messages instead.\n\n@default { type: 'all' }",
      }),
    twiml: z
      .string()
      .max(4096)
      .exactOptional()
      .openapi({
        description:
          'This is the TwiML instructions to execute on the destination call leg before connecting the customer.\n\nUsage:\n- Used only when `mode` is `warm-transfer-twiml`.\n- Supports only `Play`, `Say`, `Gather`, `Hangup` and `Pause` verbs.\n- Maximum length is 4096 characters.\n\nExample:\n```\n<Say voice="alice" language="en-US">Hello, transferring a customer to you.</Say>\n<Pause length="2"/>\n<Say>They called about billing questions.</Say>\n```',
      }),
    summaryPlan: SummaryPlanSchema.exactOptional().openapi({
      description:
        'This is the plan for generating a summary of the call to present to the destination party.\n\nUsage:\n- Used only when `mode` is `blind-transfer-add-summary-to-sip-header` or `warm-transfer-say-summary` or `warm-transfer-wait-for-operator-to-speak-first-and-then-say-summary` or `warm-transfer-experimental`.',
    }),
    sipHeadersInReferToEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This flag includes the sipHeaders from above in the refer to sip uri as url encoded query params.\n\n@default false',
      }),
    fallbackPlan: TransferFallbackPlanSchema.exactOptional().openapi({
      description:
        'This configures the fallback plan when the transfer fails (destination unreachable, busy, or not human).\n\nUsage:\n- Used when `mode` is `warm-transfer-experimental`. If not provided, a default message will be used.\n- Used for SIP cold transfers (`blind-transfer` modes) when transfer outcome detection and fallback\n  are enabled for the organization: on a failed transfer, the assistant speaks `message`, then ends\n  the call or continues with the customer per `endCallEnabled`.',
    }),
  })
  .openapi({ required: ['mode'] })
  .openapi('TransferPlan')

const TransferDestinationNumberSchema = z
  .object({
    message: z
      .xor([z.string(), CustomMessageSchema])
      .exactOptional()
      .openapi({
        description:
          'This is spoken to the customer before connecting them to the destination.\n\nUsage:\n- If this is not provided and transfer tool messages is not provided, default is "Transferring the call now".\n- If set to "", nothing is spoken. This is useful when you want to silently transfer. This is especially useful when transferring between assistants in a squad. In this scenario, you likely also want to set `assistant.firstMessageMode=assistant-speaks-first-with-model-generated-message` for the destination assistant.\n\nThis accepts a string or a ToolMessageStart class. Latter is useful if you want to specify multiple messages for different languages through the `contents` field.',
      }),
    type: z.literal('number'),
    numberE164CheckEnabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'This is the flag to toggle the E164 check for the `number` field. This is an advanced property which should be used if you know your use case requires it.\n\nUse cases:\n- `false`: To allow non-E164 numbers like `+001234567890`, `1234`, or `abc`. This is useful for dialing out to non-E164 numbers on your SIP trunks.\n- `true` (default): To allow only E164 numbers like `+14155551234`. This is standard for PSTN calls.\n\nIf `false`, the `number` is still required to only contain alphanumeric characters (regex: `/^\\+?[a-zA-Z0-9]+$/`).\n\n@default true (E164 check is enabled)',
      }),
    number: z
      .string()
      .min(3)
      .max(40)
      .openapi({ description: 'This is the phone number to transfer the call to.' }),
    extension: z
      .string()
      .min(1)
      .max(10)
      .exactOptional()
      .openapi({
        description: 'This is the extension to dial after transferring the call to the `number`.',
      }),
    callerId: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({
        description:
          "This is the caller ID to use when transferring the call to the `number`.\n\nUsage:\n- If not provided, the caller ID will be the number the call is coming **from**.\n  Example: a customer with number +14151111111 calls in to and the assistant transfers out to +16470000000. +16470000000 will see +14151111111 as the caller.\n  For inbound calls, the caller ID is the customer's number. For outbound calls, the caller ID is the phone number of the assistant.\n- To change this behavior, provide a `callerId`.\n- Set to '{{customer.number}}' to always use the customer's number as the caller ID.\n- Set to '{{phoneNumber.number}}' to always use the phone number of the assistant as the caller ID.\n- Set to any E164 number to always use that number as the caller ID. This needs to be a number that is owned or verified by your Transport provider like Twilio.\n\nNote: on Twilio, a caller who withheld their number has no caller ID the destination carrier will accept, so the assistant's phone number is presented instead and the transfer goes through. This applies when `callerId` is not provided and when it is set to '{{customer.number}}'.\n\nFor Twilio, you can read up more here: https://www.twilio.com/docs/voice/twiml/dial#callerid",
      }),
    transferPlan: TransferPlanSchema.exactOptional().openapi({
      description:
        "This configures how transfer is executed and the experience of the destination party receiving the call. Defaults to `blind-transfer`.\n\n@default `transferPlan.mode='blind-transfer'`",
    }),
    name: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({
        description:
          'This is the name of the transfer destination. This is just for your own reference.\n\nUsage:\n- Optional. Stored with the destination wherever it is supplied. For `number`\n  and `sip` destinations it is also persisted on the transfer record in the\n  call artifact after a transfer and displayed in the dashboard call log (on\n  the transfer divider in the transcript view) alongside the destination.\n  When omitted, everything behaves exactly as before.\n- Display-only. Unlike `description`, it is never included in prompts or tool\n  descriptions and has no effect on model behavior or destination choice.',
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the description of the destination, used by the AI to choose when and how to transfer the call.',
      }),
  })
  .openapi({ required: ['type', 'number'] })
  .openapi('TransferDestinationNumber')

const TransferDestinationSipSchema = z
  .object({
    message: z
      .xor([z.string(), CustomMessageSchema])
      .exactOptional()
      .openapi({
        description:
          'This is spoken to the customer before connecting them to the destination.\n\nUsage:\n- If this is not provided and transfer tool messages is not provided, default is "Transferring the call now".\n- If set to "", nothing is spoken. This is useful when you want to silently transfer. This is especially useful when transferring between assistants in a squad. In this scenario, you likely also want to set `assistant.firstMessageMode=assistant-speaks-first-with-model-generated-message` for the destination assistant.\n\nThis accepts a string or a ToolMessageStart class. Latter is useful if you want to specify multiple messages for different languages through the `contents` field.',
      }),
    type: z.literal('sip'),
    sipUri: z.string().openapi({ description: 'This is the SIP URI to transfer the call to.' }),
    callerId: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({
        description:
          "This is the caller ID to use when transferring the call to the `sipUri`.\n\nUsage:\n- If not provided, the caller ID will be determined by the SIP infrastructure.\n- Set to '{{customer.number}}' to always use the customer's number as the caller ID.\n- Set to '{{phoneNumber.number}}' to always use the phone number of the assistant as the caller ID.\n- Set to any E164 number to always use that number as the caller ID.\n\nOnly applicable when `transferPlan.sipVerb='dial'`. Not applicable for SIP REFER.",
      }),
    transferPlan: TransferPlanSchema.exactOptional().openapi({
      description:
        "This configures how transfer is executed and the experience of the destination party receiving the call. Defaults to `blind-transfer`.\n\n@default `transferPlan.mode='blind-transfer'`",
    }),
    sipHeaders: z
      .object({})
      .exactOptional()
      .openapi({
        description: 'These are custom headers to be added to SIP refer during transfer call.',
      }),
    name: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({
        description:
          'This is the name of the transfer destination. This is just for your own reference.\n\nUsage:\n- Optional. Stored with the destination wherever it is supplied. For `number`\n  and `sip` destinations it is also persisted on the transfer record in the\n  call artifact after a transfer and displayed in the dashboard call log (on\n  the transfer divider in the transcript view) alongside the destination.\n  When omitted, everything behaves exactly as before.\n- Display-only. Unlike `description`, it is never included in prompts or tool\n  descriptions and has no effect on model behavior or destination choice.',
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the description of the destination, used by the AI to choose when and how to transfer the call.',
      }),
  })
  .openapi({ required: ['type', 'sipUri'] })
  .openapi('TransferDestinationSip')

