const SecurityFilterBaseSchema = z.object({}).openapi('SecurityFilterBase')

const SecurityFilterPlanSchema = z
  .object({
    enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({ description: 'Whether the security filter is enabled.\n@default false' }),
    filters: z
      .array(SecurityFilterBaseSchema)
      .exactOptional()
      .openapi({
        description:
          'Array of security filter types to apply.\nIf array is not empty, only those security filters are run.',
        example: '[{ type: "sql-injection" }, { type: "xss" }]',
      }),
    mode: z
      .enum(['sanitize', 'reject', 'replace'])
      .default('sanitize')
      .exactOptional()
      .openapi({
        description:
          "Mode of operation when a security threat is detected.\n- 'sanitize': Remove or replace the threatening content\n- 'reject': Replace the entire transcript with replacement text\n- 'replace': Replace threatening patterns with replacement text\n@default 'sanitize'",
      }),
    replacementText: z
      .string()
      .default('[FILTERED]')
      .exactOptional()
      .openapi({
        description: "Text to use when replacing filtered content.\n@default '[FILTERED]'",
      }),
  })
  .openapi({ required: [] })
  .openapi('SecurityFilterPlan')

const ExactReplacementSchema = z
  .object({
    type: z
      .literal('exact')
      .openapi({
        description:
          "This is the exact replacement type. You can use this to replace a specific word or phrase with a different word or phrase.\n\nUsage:\n- Replace \"hello\" with \"hi\": { type: 'exact', key: 'hello', value: 'hi' }\n- Replace \"good morning\" with \"good day\": { type: 'exact', key: 'good morning', value: 'good day' }\n- Replace a specific name: { type: 'exact', key: 'John Doe', value: 'Jane Smith' }\n- Replace an acronym: { type: 'exact', key: 'AI', value: 'Artificial Intelligence' }\n- Replace a company name with its phonetic pronunciation: { type: 'exact', key: 'Vapi', value: 'Vappy' }",
      }),
    replaceAllEnabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "This option let's you control whether to replace all instances of the key or only the first one. By default, it only replaces the first instance.\nExamples:\n- For { type: 'exact', key: 'hello', value: 'hi', replaceAllEnabled: false }. Before: \"hello world, hello universe\" | After: \"hi world, hello universe\"\n- For { type: 'exact', key: 'hello', value: 'hi', replaceAllEnabled: true }. Before: \"hello world, hello universe\" | After: \"hi world, hi universe\"\n@default false",
      }),
    key: z.string().openapi({ description: 'This is the key to replace.' }),
    value: z
      .string()
      .max(1000)
      .openapi({ description: 'This is the value that will replace the match.' }),
  })
  .openapi({ required: ['type', 'key', 'value'] })
  .openapi('ExactReplacement')

const RegexReplacementSchema = z
  .object({
    type: z
      .literal('regex')
      .openapi({
        description:
          "This is the regex replacement type. You can use this to replace a word or phrase that matches a pattern.\n\nUsage:\n- Replace all numbers with \"some number\": { type: 'regex', regex: '\\\\d+', value: 'some number' }\n- Replace email addresses with \"[EMAIL]\": { type: 'regex', regex: '\\\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\\\.[A-Z|a-z]{2,}\\\\b', value: '[EMAIL]' }\n- Replace phone numbers with a formatted version: { type: 'regex', regex: '(\\\\d{3})(\\\\d{3})(\\\\d{4})', value: '($1) $2-$3' }\n- Replace all instances of \"color\" or \"colour\" with \"hue\": { type: 'regex', regex: 'colou?r', value: 'hue' }\n- Capitalize the first letter of every sentence: { type: 'regex', regex: '(?<=\\\\. |^)[a-z]', value: (match) => match.toUpperCase() }",
      }),
    regex: z
      .string()
      .openapi({
        description:
          'This is the regex pattern to replace.\n\nNote:\n- This works by using the `string.replace` method in Node.JS. Eg. `"hello there".replace(/hello/g, "hi")` will return `"hi there"`.\n\nHot tip:\n- In JavaScript, escape `\\` when sending the regex pattern. Eg. `"hello\\sthere"` will be sent over the wire as `"hellosthere"`. Send `"hello\\\\sthere"` instead.',
      }),
    options: z
      .array(RegexOptionSchema)
      .exactOptional()
      .openapi({
        description:
          'These are the options for the regex replacement. Defaults to all disabled.\n\n@default []',
      }),
    value: z
      .string()
      .max(1000)
      .openapi({ description: 'This is the value that will replace the match.' }),
  })
  .openapi({ required: ['type', 'regex', 'value'] })
  .openapi('RegexReplacement')

const FormatPlanSchema = z
  .object({
    enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "This determines whether the chunk is formatted before being sent to the voice provider. This helps with enunciation. This includes phone numbers, emails and addresses. Default `true`.\n\nUsage:\n- To rely on the voice provider's formatting logic, set this to `false`.\n\nIf `voice.chunkPlan.enabled` is `false`, this is automatically `false` since there's no chunk to format.\n\n@default true",
        example: true,
      }),
    numberToDigitsCutoff: z
      .number()
      .min(0)
      .exactOptional()
      .openapi({
        description:
          'This is the cutoff after which a number is converted to individual digits instead of being spoken as words.\n\nExample:\n- If cutoff 2025, "12345" is converted to "1 2 3 4 5" while "1200" is converted to "twelve hundred".\n\nUsage:\n- If your use case doesn\'t involve IDs like zip codes, set this to a high value.\n- If your use case involves IDs that are shorter than 5 digits, set this to a lower value.\n\n@default 2025',
        example: 2025,
      }),
    replacements: z
      .array(
        z.xor([
          ExactReplacementSchema.openapi({ title: 'ExactReplacement' }),
          RegexReplacementSchema.openapi({ title: 'RegexReplacement' }),
        ]),
      )
      .exactOptional()
      .openapi({
        description:
          "These are the custom replacements you can make to the chunk before it is sent to the voice provider.\n\nUsage:\n- To replace a specific word or phrase with a different word or phrase, use the `ExactReplacement` type. Eg. `{ type: 'exact', key: 'hello', value: 'hi' }`\n- To replace a word or phrase that matches a pattern, use the `RegexReplacement` type. Eg. `{ type: 'regex', regex: '\\\\b[a-zA-Z]{5}\\\\b', value: 'hi' }`\n\n@default []",
      }),
    formattersEnabled: z
      .union([
        z.literal('markdown'),
        z.literal('asterisk'),
        z.literal('quote'),
        z.literal('dash'),
        z.literal('newline'),
        z.literal('colon'),
        z.literal('acronym'),
        z.literal('dollarAmount'),
        z.literal('email'),
        z.literal('date'),
        z.literal('time'),
        z.literal('distance'),
        z.literal('unit'),
        z.literal('percentage'),
        z.literal('phoneNumber'),
        z.literal('number'),
        z.literal('stripAsterisk'),
      ])
      .exactOptional()
      .openapi({
        description:
          'List of formatters to apply. If not provided, all default formatters will be applied.\nIf provided, only the specified formatters will be applied.\nNote: Some essential formatters like angle bracket removal will always be applied.\n@default undefined',
      }),
  })
  .openapi({ required: [] })
  .openapi('FormatPlan')

const ChunkPlanSchema = z
  .object({
    enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "This determines whether the model output is chunked before being sent to the voice provider. Default `true`.\n\nUsage:\n- To rely on the voice provider's audio generation logic, set this to `false`.\n- If seeing issues with quality, set this to `true`.\n\nIf disabled, Vapi-provided audio control tokens like <flush /> will not work.\n\n@default true",
        example: true,
      }),
    minCharacters: z
      .number()
      .min(1)
      .max(80)
      .exactOptional()
      .openapi({
        description:
          'This is the minimum number of characters in a chunk.\n\nUsage:\n- To increase quality, set this to a higher value.\n- To decrease latency, set this to a lower value.\n\n@default 30',
        example: 30,
      }),
    punctuationBoundaries: z
      .union([
        z.literal('。'),
        z.literal('，'),
        z.literal('.'),
        z.literal('!'),
        z.literal('?'),
        z.literal(';'),
        z.literal(')'),
        z.literal('،'),
        z.literal('۔'),
        z.literal('।'),
        z.literal('॥'),
        z.literal('|'),
        z.literal('||'),
        z.literal(','),
        z.literal(':'),
      ])
      .exactOptional()
      .openapi({
        description:
          'These are the punctuations that are considered valid boundaries for a chunk to be created.\n\nUsage:\n- To increase quality, constrain to fewer boundaries.\n- To decrease latency, enable all.\n\nDefault is automatically set to balance the trade-off between quality and latency based on the provider.',
        example: ['。', '，', '.', '!', '?', ';', '،', '۔', '।', '॥', '|', '||', ',', ':'],
      }),
    formatPlan: FormatPlanSchema.exactOptional().openapi({
      description:
        'This is the plan for formatting the chunk before it is sent to the voice provider.',
    }),
  })
  .openapi({ required: [] })
  .openapi('ChunkPlan')

