const RecordingConsentPlanStayOnLineSchema = z
  .object({
    message: z
      .string()
      .max(1000)
      .openapi({
        description:
          'This is the message asking for consent to record the call.\nIf the type is `stay-on-line`, the message should ask the user to hang up if they do not consent.\nIf the type is `verbal`, the message should ask the user to verbally consent or decline.',
        examples: [
          'For quality purposes, this call may be recorded. Please stay on the line if you agree or end the call if you do not consent.',
          'This call may be recorded for quality and training purposes. Say "I agree" if you consent to being recorded, or "I disagree" if you do not consent.',
        ],
      }),
    voice: z
      .xor([
        AzureVoiceSchema.openapi({ title: 'AzureVoice' }),
        CartesiaVoiceSchema.openapi({ title: 'CartesiaVoice' }),
        CustomVoiceSchema.openapi({ title: 'CustomVoice' }),
        DeepgramVoiceSchema.openapi({ title: 'DeepgramVoice' }),
        ElevenLabsVoiceSchema.openapi({ title: 'ElevenLabsVoice' }),
        HumeVoiceSchema.openapi({ title: 'HumeVoice' }),
        LMNTVoiceSchema.openapi({ title: 'LMNTVoice' }),
        NeuphonicVoiceSchema.openapi({ title: 'NeuphonicVoice' }),
        OpenAIVoiceSchema.openapi({ title: 'OpenAIVoice' }),
        PlayHTVoiceSchema.openapi({ title: 'PlayHTVoice' }),
        WellSaidVoiceSchema.openapi({ title: 'WellSaidVoice' }),
        RimeAIVoiceSchema.openapi({ title: 'RimeAIVoice' }),
        SmallestAIVoiceSchema.openapi({ title: 'SmallestAIVoice' }),
        VapiVoiceSchema.openapi({ title: 'VapiVoice' }),
        SesameVoiceSchema.openapi({ title: 'SesameVoice' }),
        InworldVoiceSchema.openapi({ title: 'InworldVoice' }),
        MinimaxVoiceSchema.openapi({ title: 'MinimaxVoice' }),
        XaiVoiceSchema.openapi({ title: 'XaiVoice' }),
        MicrosoftVoiceSchema.openapi({ title: 'MicrosoftVoice' }),
      ])
      .exactOptional()
      .openapi({
        description:
          "This is the voice to use for the consent message. If not specified, inherits from the assistant's voice.\nUse a different voice for the consent message for a better user experience.",
      }),
    firstMessageMode: z
      .enum(['assistant-speaks-first', 'assistant-waits-for-user'])
      .default('assistant-speaks-first')
      .exactOptional()
      .openapi({
        description:
          "This controls whether the consent assistant speaks first or waits for the caller to speak first.\n\nUse:\n- `assistant-speaks-first` (default) to have the consent assistant play the consent message as soon as the call is answered.\n- `assistant-waits-for-user` to have the consent assistant wait for the caller to speak before playing the consent message.\n\nWe strongly recommend `assistant-waits-for-user` for outbound calls. Some telephony providers signal \"answered\" while the line is still ringing, which can cause the consent message to play into a ringing line and be missed by the caller. Waiting for the caller to speak first guarantees they hear the full consent message.\n\nNote: when combined with `type: 'stay-on-line'`, silence only counts toward consent after the caller has spoken at least once.\n\n@default 'assistant-speaks-first'",
        example: 'assistant-speaks-first',
      }),
    type: z
      .literal('stay-on-line')
      .openapi({
        description:
          'This is the type of recording consent plan. This type assumes consent is granted if the user stays on the line.',
        example: 'stay-on-line',
      }),
    waitSeconds: z
      .number()
      .min(1)
      .max(6)
      .default(3)
      .exactOptional()
      .openapi({
        description:
          'Number of seconds to wait before transferring to the assistant if user stays on the call',
        example: 3,
      }),
  })
  .openapi({ required: ['message', 'type'] })
  .openapi('RecordingConsentPlanStayOnLine')

