const NumberComparatorScorecardMetricConditionSchema = z
  .object({
    type: z
      .literal('comparator')
      .openapi({
        description: "This is the type of the condition. Currently only 'comparator' is supported.",
      }),
    comparator: z
      .enum(['=', '!=', '>', '<', '>=', '<='])
      .openapi({
        description:
          "This is the comparator that will be used to compare the result of the structured output with the value specified.\nOnly '=', '!=', '>', '<', '>=', and '<=' are supported for number conditions\nOnly '=' is supported for boolean conditions.",
      }),
    value: z
      .number()
      .openapi({
        description:
          'This is the value that will be used to compare the result of the structured output with the comparator.\nIf the result of the comparison is true, the points will be added to the overall score.',
      }),
    points: z
      .number()
      .min(0)
      .max(100)
      .openapi({
        description:
          'These are the points that will be added to the overall score if the condition is met.\nThe points must be between 0 and 100.',
      }),
  })
  .openapi({ required: ['type', 'comparator', 'value', 'points'] })
  .openapi('NumberComparatorScorecardMetricCondition')

const BooleanComparatorScorecardMetricConditionSchema = z
  .object({
    type: z
      .literal('comparator')
      .openapi({
        description: "This is the type of the condition. Currently only 'comparator' is supported.",
      }),
    comparator: z
      .literal('=')
      .openapi({ description: "The comparator can only be '=' for boolean conditions." }),
    value: z
      .boolean()
      .openapi({
        description:
          'This is the value that will be used to compare the result of the structured output with the comparator.\nIf the result of the comparison is true, the points will be added to the overall score.',
      }),
    points: z
      .number()
      .min(0)
      .max(100)
      .openapi({
        description:
          'These are the points that will be added to the overall score if the condition is met.\nThe points must be between 0 and 100.',
      }),
  })
  .openapi({ required: ['type', 'comparator', 'value', 'points'] })
  .openapi('BooleanComparatorScorecardMetricCondition')

const ScorecardMetricSchema = z
  .object({
    conditions: z
      .array(
        z.xor([
          NumberComparatorScorecardMetricConditionSchema.openapi({
            title: 'NumberComparatorScorecardMetricCondition',
          }),
          BooleanComparatorScorecardMetricConditionSchema.openapi({
            title: 'BooleanComparatorScorecardMetricCondition',
          }),
        ]),
      )
      .openapi({
        description:
          'These are the conditions that will be used to evaluate the scorecard.\nEach condition will have a comparator, value, and points that will be used to calculate the final score.\nThe points will be added to the overall score if the condition is met.\nThe overall score will be normalized to a 100 point scale to ensure uniformity across different scorecards.',
      }),
    structuredOutputId: z
      .string()
      .openapi({
        description:
          'This is the unique identifier for the structured output that will be used to evaluate the scorecard.\nThe structured output must be of type number or boolean only for now.',
      }),
  })
  .openapi({ required: ['conditions', 'structuredOutputId'] })
  .openapi('ScorecardMetric')

const CreateScorecardDTOSchema = z
  .object({
    name: z
      .string()
      .max(80)
      .exactOptional()
      .openapi({
        description:
          'This is the name of the scorecard. It is only for user reference and will not be used for any evaluation.',
      }),
    description: z
      .string()
      .max(500)
      .exactOptional()
      .openapi({
        description:
          'This is the description of the scorecard. It is only for user reference and will not be used for any evaluation.',
      }),
    metrics: z
      .array(ScorecardMetricSchema)
      .openapi({
        description:
          'These are the metrics that will be used to evaluate the scorecard.\nEach metric will have a set of conditions and points that will be used to generate the score.',
      }),
    assistantIds: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          "These are the assistant IDs that this scorecard is linked to.\nWhen linked to assistants, this scorecard will be available for evaluation during those assistants' calls.",
      }),
  })
  .openapi({ required: ['metrics'] })
  .openapi('CreateScorecardDTO')

type ArtifactPlanType = {
  recordingEnabled?: boolean
  recordingFormat?: 'wav;l16' | 'mp3'
  recordingUseCustomStorageEnabled?: boolean
  videoRecordingEnabled?: boolean
  fullMessageHistoryEnabled?: boolean
  pcapEnabled?: boolean
  pcapS3PathPrefix?: string
  pcapUseCustomStorageEnabled?: boolean
  loggingEnabled?: boolean
  loggingUseCustomStorageEnabled?: boolean
  transcriptPlan?: z.infer<typeof TranscriptPlanSchema>
  recordingPath?: string
  structuredOutputIds?: string[]
  structuredOutputs?: z.infer<typeof CreateStructuredOutputDTOSchema>[]
  scorecardIds?: string[]
  scorecards?: z.infer<typeof CreateScorecardDTOSchema>[]
  loggingPath?: string
}

type StopSpeakingPlanType = {
  numWords?: number
  voiceSeconds?: number
  backoffSeconds?: number
  acknowledgementPhrases?: string[]
  interruptionPhrases?: string[]
}

type MonitorPlanType = {
  listenEnabled?: boolean
  listenAuthenticationEnabled?: boolean
  controlEnabled?: boolean
  controlAuthenticationEnabled?: boolean
  monitorIds?: string[]
}

type KeypadInputPlanType = {
  enabled?: boolean
  timeoutSeconds?: number
  delimiters?: '#' | '*' | ''
}

