const GoogleVoicemailDetectionPlanSchema: z.ZodType<GoogleVoicemailDetectionPlanType> = z
  .object({
    beepMaxAwaitSeconds: z
      .number()
      .min(0)
      .max(30)
      .default(30)
      .exactOptional()
      .openapi({
        description:
          'This is the maximum duration from the start of the call that we will wait for a voicemail beep, before speaking our message\n\n- If we detect a voicemail beep before this, we will speak the message at that point.\n\n- Setting too low a value means that the bot will start speaking its voicemail message too early. If it does so before the actual beep, it will get cut off. You should definitely tune this to your use case.\n\n@default 30\n@min 0\n@max 60',
      }),
    provider: z
      .literal('google')
      .openapi({ description: 'This is the provider to use for voicemail detection.' }),
    backoffPlan: VoicemailDetectionBackoffPlanSchema.exactOptional().openapi({
      description: 'This is the backoff plan for the voicemail detection.',
    }),
    type: z
      .enum(['audio', 'transcript'])
      .exactOptional()
      .openapi({
        description:
          "This is the detection type to use for voicemail detection.\n- 'audio': Uses native audio models (default)\n- 'transcript': Uses ASR/transcript-based detection\n@default 'audio' (audio detection)",
      }),
  })
  .openapi({ required: ['provider'] })
  .openapi('GoogleVoicemailDetectionPlan')

