const CallHookCallEndingSchema: z.ZodType<CallHookCallEndingType> = z
  .lazy(() =>
    z
      .object({
        on: z
          .literal('call.ending')
          .openapi({ description: 'This is the event that triggers this hook' }),
        do: z
          .array(
            z.xor([
              ToolCallHookActionSchema.openapi({ title: 'ToolCallHookAction' }),
              MessageAddHookActionSchema.openapi({ title: 'MessageAddHookAction' }),
            ]),
          )
          .openapi({ description: 'This is the set of actions to perform when the hook triggers' }),
        filters: z
          .array(CallHookFilterSchema)
          .exactOptional()
          .openapi({
            description: 'This is the set of filters that must match for the hook to trigger',
          }),
      })
      .openapi({ required: ['on', 'do'] }),
  )
  .openapi('CallHookCallEnding')

