const CompliancePlanSchema: z.ZodType<CompliancePlanType> = z
  .object({
    hipaaEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When this is enabled, logs, recordings, and transcriptions will be stored in HIPAA-compliant storage. Defaults to false. Only HIPAA-compliant providers will be available for LLM, Voice, and Transcriber respectively. This setting is only honored if the organization is on an Enterprise subscription or has purchased the HIPAA add-on.',
      }),
    pciEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'When this is enabled, the user will be restricted to use PCI-compliant providers, and no logs or transcripts are stored.\nAt the end of the call, you will receive an end-of-call-report message to store on your server. Defaults to false.',
        example: { pciEnabled: false },
      }),
    securityFilterPlan: SecurityFilterPlanSchema.exactOptional().openapi({
      description:
        'This is the security filter plan for the assistant. It allows filtering of transcripts for security threats before sending to LLM.',
    }),
    recordingConsentPlan: z
      .xor([
        RecordingConsentPlanStayOnLineSchema.openapi({ title: 'RecordingConsentStayOnLinePlan' }),
        RecordingConsentPlanVerbalSchema.openapi({ title: 'RecordingConsentPlanVerbal' }),
      ])
      .exactOptional()
      .openapi({
        discriminator: {
          propertyName: 'type',
          mapping: {
            'stay-on-line': '#/components/schemas/RecordingConsentPlanStayOnLine',
            verbal: '#/components/schemas/RecordingConsentPlanVerbal',
          },
        },
      }),
  })
  .openapi({ required: [] })
  .openapi('CompliancePlan')

