const ArtifactPlanSchema: z.ZodType<ArtifactPlanType> = z
  .object({
    recordingEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "This determines whether assistant's calls are recorded. Defaults to true.\n\nUsage:\n- If you don't want to record the calls, set this to false.\n- If you want to record the calls when `assistant.hipaaEnabled` (deprecated) or `assistant.compliancePlan.hipaaEnabled` explicity set this to true and make sure to provide S3 or GCP credentials on the Provider Credentials page in the Dashboard.\n\nYou can find the recording at `call.artifact.recordingUrl` and `call.artifact.stereoRecordingUrl` after the call is ended.\n\n@default true",
        example: true,
      }),
    recordingFormat: z
      .enum(['wav;l16', 'mp3'])
      .exactOptional()
      .openapi({
        description:
          "This determines the format of the recording. Defaults to `wav;l16`.\n\n@default 'wav;l16'",
      }),
    recordingUseCustomStorageEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether to use custom storage (S3 or GCP) for call recordings when storage credentials are configured.\n\nWhen set to false, recordings will be stored on Vapi\'s storage instead of your custom storage, even if you have custom storage credentials configured.\n\nUsage:\n- Set to false if you have custom storage configured but want to store recordings on Vapi\'s storage for this assistant.\n- Set to true (or leave unset) to use your custom storage for recordings when available.\n\nIf your organization has ZDR (zero data retention) or PCI enabled, recordings are never written to Vapi storage. In that case, false means "do not use my custom storage", so nothing is stored at all.\n\n@default true',
        example: true,
      }),
    videoRecordingEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether the video is recorded during the call. Defaults to false. Only relevant for `webCall` type.\n\nYou can find the video recording at `call.artifact.videoRecordingUrl` after the call is ended.\n\n@default false',
        example: false,
      }),
    fullMessageHistoryEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether the artifact contains the full message history, even after handoff context engineering. Defaults to false.',
        example: false,
      }),
    pcapEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "This determines whether the SIP packet capture is enabled. Defaults to true. Only relevant for `phone` type calls where phone number's provider is `vapi` or `byo-phone-number`.\n\nYou can find the packet capture at `call.artifact.pcapUrl` after the call is ended.\n\n@default true",
        example: true,
      }),
    pcapS3PathPrefix: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is the path where the SIP packet capture will be uploaded. This is only used if you have provided S3 or GCP credentials on the Provider Credentials page in the Dashboard.\n\nIf credential.s3PathPrefix or credential.bucketPlan.path is set, this will append to it.\n\nUsage:\n- If you want to upload the packet capture to a specific path, set this to the path. Example: `/my-assistant-captures`.\n- If you want to upload the packet capture to the root of the bucket, set this to `/`.\n\n@default '/'",
        example: '/pcaps',
      }),
    pcapUseCustomStorageEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether to use custom storage (S3 or GCP) for SIP packet captures when storage credentials are configured.\n\nWhen set to false, packet captures will be stored on Vapi\'s storage instead of your custom storage, even if you have custom storage credentials configured.\n\nUsage:\n- Set to false if you have custom storage configured but want to store packet captures on Vapi\'s storage for this assistant.\n- Set to true (or leave unset) to use your custom storage for packet captures when available.\n\nIf your organization has ZDR (zero data retention) or PCI enabled, packet captures are never written to Vapi storage. In that case, false means "do not use my custom storage", so nothing is stored at all.\n\n@default true',
        example: true,
      }),
    loggingEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether the call logs are enabled. Defaults to true.\n\n@default true',
        example: true,
      }),
    loggingUseCustomStorageEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This determines whether to use custom storage (S3 or GCP) for call logs when storage credentials are configured.\n\nWhen set to false, logs will be stored on Vapi\'s storage instead of your custom storage, even if you have custom storage credentials configured.\n\nUsage:\n- Set to false if you have custom storage configured but want to store logs on Vapi\'s storage for this assistant.\n- Set to true (or leave unset) to use your custom storage for logs when available.\n\nIf your organization has ZDR (zero data retention) or PCI enabled, logs are never written to Vapi storage. In that case, false means "do not use my custom storage", so nothing is stored at all.\n\n@default true',
        example: true,
      }),
    transcriptPlan: TranscriptPlanSchema.exactOptional().openapi({
      description:
        'This is the plan for `call.artifact.transcript`. To disable, set `transcriptPlan.enabled` to false.',
    }),
    recordingPath: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is the path where the recording will be uploaded. This is only used if you have provided S3 or GCP credentials on the Provider Credentials page in the Dashboard.\n\nIf credential.s3PathPrefix or credential.bucketPlan.path is set, this will append to it.\n\nUsage:\n- If you want to upload the recording to a specific path, set this to the path. Example: `/my-assistant-recordings`.\n- If you want to upload the recording to the root of the bucket, set this to `/`.\n\n@default '/'",
      }),
    structuredOutputIds: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'This is an array of structured output IDs to be calculated during the call.\nThe outputs will be extracted and stored in `call.artifact.structuredOutputs` after the call is ended.',
      }),
    structuredOutputs: z
      .array(CreateStructuredOutputDTOSchema)
      .exactOptional()
      .openapi({
        description:
          'This is an array of transient structured outputs to be calculated during the call.\nThe outputs will be extracted and stored in `call.artifact.structuredOutputs` after the call is ended.\nUse this to provide inline structured output configurations instead of referencing existing ones via structuredOutputIds.',
      }),
    scorecardIds: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'This is an array of scorecard IDs that will be evaluated based on the structured outputs extracted during the call.\nThe scorecards will be evaluated and the results will be stored in `call.artifact.scorecards` after the call has ended.',
      }),
    scorecards: z
      .array(CreateScorecardDTOSchema)
      .exactOptional()
      .openapi({
        description:
          'This is the array of scorecards that will be evaluated based on the structured outputs extracted during the call.\nThe scorecards will be evaluated and the results will be stored in `call.artifact.scorecards` after the call has ended.',
      }),
    loggingPath: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is the path where the call logs will be uploaded. This is only used if you have provided S3 or GCP credentials on the Provider Credentials page in the Dashboard.\n\nIf credential.s3PathPrefix or credential.bucketPlan.path is set, this will append to it.\n\nUsage:\n- If you want to upload the call logs to a specific path, set this to the path. Example: `/my-assistant-logs`.\n- If you want to upload the call logs to the root of the bucket, set this to `/`.\n\n@default '/'",
      }),
  })
  .openapi({ required: [] })
  .openapi('ArtifactPlan')

const StartSpeakingPlanSchema: z.ZodType<StartSpeakingPlanType> = z
  .object({
    waitSeconds: z
      .number()
      .min(0)
      .max(5)
      .exactOptional()
      .openapi({
        description:
          'This is how long assistant waits before speaking. Defaults to 0.4.\n\nThis is the minimum it will wait but if there is latency is the pipeline, this minimum will be exceeded. This is intended as a stopgap in case the pipeline is moving too fast.\n\nExample:\n- If model generates tokens and voice generates bytes within 100ms, the pipeline still waits 300ms before outputting speech.\n\nUsage:\n- If the customer is taking long pauses, set this to a higher value.\n- If the assistant is accidentally jumping in too much, set this to a higher value.\n\n@default 0.4',
        example: 0.4,
      }),
    smartEndpointingEnabled: z
      .xor([z.boolean(), z.literal('livekit')])
      .exactOptional()
      .openapi({ example: false, deprecated: true }),
    smartEndpointingPlan: z
      .xor([
        VapiSmartEndpointingPlanSchema.openapi({ title: 'Vapi' }),
        LivekitSmartEndpointingPlanSchema.openapi({ title: 'Livekit' }),
        CustomEndpointingModelSmartEndpointingPlanSchema.openapi({
          title: 'Custom Endpointing Model',
        }),
      ])
      .exactOptional()
      .openapi({
        description:
          "This is the plan for smart endpointing. Pick between Vapi smart endpointing, LiveKit, or custom endpointing model (or nothing). We strongly recommend using livekit endpointing when working in English. LiveKit endpointing is not supported in other languages, yet.\n\nIf this is set, it will override and take precedence over `transcriptionEndpointingPlan`.\nThis plan will still be overridden by any matching `customEndpointingRules`.\n\nIf this is not set, the system will automatically use the transcriber's built-in endpointing capabilities if available.",
      }),
    customEndpointingRules: z
      .array(
        z.xor([
          AssistantCustomEndpointingRuleSchema.openapi({ title: 'Assistant' }),
          CustomerCustomEndpointingRuleSchema.openapi({ title: 'Customer' }),
          BothCustomEndpointingRuleSchema.openapi({ title: 'Both' }),
        ]),
      )
      .exactOptional()
      .openapi({
        description:
          'These are the custom endpointing rules to set an endpointing timeout based on a regex on the customer\'s speech or the assistant\'s last message.\n\nUsage:\n- If you have yes/no questions like "are you interested in a loan?", you can set a shorter timeout.\n- If you have questions where the customer may pause to look up information like "what\'s my account number?", you can set a longer timeout.\n- If you want to wait longer while customer is enumerating a list of numbers, you can set a longer timeout.\n\nThese rules have the highest precedence and will override both `smartEndpointingPlan` and `transcriptionEndpointingPlan` when a rule is matched.\n\nThe rules are evaluated in order and the first one that matches will be used.\n\nOrder of precedence for endpointing:\n1. customEndpointingRules (if any match)\n2. smartEndpointingPlan (if set)\n3. transcriptionEndpointingPlan\n\n@default []',
      }),
    transcriptionEndpointingPlan: TranscriptionEndpointingPlanSchema.exactOptional().openapi({
      description:
        "This determines how a customer speech is considered done (endpointing) using the transcription of customer's speech.\n\nOnce an endpoint is triggered, the request is sent to `assistant.model`.\n\nNote: This plan is only used if `smartEndpointingPlan` is not set and transcriber does not have built-in endpointing capabilities. If both are provided, `smartEndpointingPlan` takes precedence.\nThis plan will also be overridden by any matching `customEndpointingRules`.",
    }),
  })
  .openapi({ required: [] })
  .openapi('StartSpeakingPlan')

const StopSpeakingPlanSchema: z.ZodType<StopSpeakingPlanType> = z
  .object({
    numWords: z
      .number()
      .min(0)
      .max(10)
      .exactOptional()
      .openapi({
        description:
          'This is the number of words that the customer has to say before the assistant will stop talking.\n\nWords like "stop", "actually", "no", etc. will always interrupt immediately regardless of this value.\n\nWords like "okay", "yeah", "right" will never interrupt.\n\nWhen set to 0, `voiceSeconds` is used in addition to the transcriptions to determine the customer has started speaking.\n\nDefaults to 0.\n\n@default 0',
        example: 0,
      }),
    voiceSeconds: z
      .number()
      .min(0)
      .max(0.5)
      .exactOptional()
      .openapi({
        description:
          'This is the seconds customer has to speak before the assistant stops talking. This uses the VAD (Voice Activity Detection) spike to determine if the customer has started speaking.\n\nConsiderations:\n- A lower value might be more responsive but could potentially pick up non-speech sounds.\n- A higher value reduces false positives but might slightly delay the detection of speech onset.\n\nThis is only used if `numWords` is set to 0.\n\nDefaults to 0.2\n\n@default 0.2',
        example: 0.2,
      }),
    backoffSeconds: z
      .number()
      .min(0)
      .max(10)
      .exactOptional()
      .openapi({
        description:
          'This is the seconds to wait before the assistant will start talking again after being interrupted.\n\nDefaults to 1.\n\n@default 1',
        example: 1,
      }),
    acknowledgementPhrases: z
      .array(z.string().max(240))
      .default([
        'i understand',
        'i see',
        'i got it',
        'i hear you',
        'im listening',
        'im with you',
        'right',
        'okay',
        'ok',
        'sure',
        'alright',
        'got it',
        'understood',
        'yeah',
        'yes',
        'uh-huh',
        'mm-hmm',
        'gotcha',
        'mhmm',
        'ah',
        'yeah okay',
        'yeah sure',
      ])
      .exactOptional()
      .openapi({
        description:
          'These are the phrases that will never interrupt the assistant, even if numWords threshold is met.\nThese are typically acknowledgement or backchanneling phrases.',
        example: [
          'i understand',
          'i see',
          'i got it',
          'i hear you',
          'im listening',
          'im with you',
          'right',
          'okay',
          'ok',
          'sure',
          'alright',
          'got it',
          'understood',
          'yeah',
          'yes',
          'uh-huh',
          'mm-hmm',
          'gotcha',
          'mhmm',
          'ah',
          'yeah okay',
          'yeah sure',
        ],
      }),
    interruptionPhrases: z
      .array(z.string().max(240))
      .default([
        'stop',
        'shut',
        'up',
        'enough',
        'quiet',
        'silence',
        'but',
        'dont',
        'not',
        'no',
        'hold',
        'wait',
        'cut',
        'pause',
        'nope',
        'nah',
        'nevermind',
        'never',
        'bad',
        'actually',
      ])
      .exactOptional()
      .openapi({
        description:
          'These are the phrases that will always interrupt the assistant immediately, regardless of numWords.\nThese are typically phrases indicating disagreement or desire to stop.',
        example: [
          'stop',
          'shut',
          'up',
          'enough',
          'quiet',
          'silence',
          'but',
          'dont',
          'not',
          'no',
          'hold',
          'wait',
          'cut',
          'pause',
          'nope',
          'nah',
          'nevermind',
          'never',
          'bad',
          'actually',
        ],
      }),
  })
  .openapi({ required: [] })
  .openapi('StopSpeakingPlan')

const MonitorPlanSchema: z.ZodType<MonitorPlanType> = z
  .object({
    listenEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "This determines whether the assistant's calls allow live listening. Defaults to true.\n\nFetch `call.monitor.listenUrl` to get the live listening URL.\n\n@default true",
        example: false,
      }),
    listenAuthenticationEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This enables authentication on the `call.monitor.listenUrl`.\n\nIf `listenAuthenticationEnabled` is `true`, the `call.monitor.listenUrl` will require an `Authorization: Bearer <vapi-public-api-key>` header.\n\n@default false',
        example: false,
      }),
    controlEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "This determines whether the assistant's calls allow live control. Defaults to true.\n\nFetch `call.monitor.controlUrl` to get the live control URL.\n\nTo use, send any control message via a POST request to `call.monitor.controlUrl`. Here are the types of controls supported: https://docs.vapi.ai/api-reference/messages/client-inbound-message\n\n@default true",
        example: false,
      }),
    controlAuthenticationEnabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This enables authentication on the `call.monitor.controlUrl`.\n\nIf `controlAuthenticationEnabled` is `true`, the `call.monitor.controlUrl` will require an `Authorization: Bearer <vapi-public-api-key>` header.\n\n@default false',
        example: false,
      }),
    monitorIds: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'This the set of monitor ids that are attached to the assistant.\nThe source of truth for the monitor ids is the assistant_monitor join table.\nThis field can be used for transient assistants and to update assistants with new monitor ids.\n\n@default []',
        example: ['123e4567-e89b-12d3-a456-426614174000'],
      }),
  })
  .openapi({ required: [] })
  .openapi('MonitorPlan')

const KeypadInputPlanSchema: z.ZodType<KeypadInputPlanType> = z
  .object({
    enabled: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This keeps track of whether the user has enabled keypad input.\nBy default, it is off.\n\n@default false',
      }),
    timeoutSeconds: z
      .number()
      .min(0)
      .max(10)
      .exactOptional()
      .openapi({
        description:
          'This is the time in seconds to wait before processing the input.\nIf the input is not received within this time, the input will be ignored.\nIf set to "off", the input will be processed when the user enters a delimiter or immediately if no delimiter is used.\n\n@default 2',
      }),
    delimiters: z
      .enum(['#', '*', ''])
      .exactOptional()
      .openapi({
        description:
          "This is the delimiter(s) that will be used to process the input.\nCan be '#', '*', or an empty array.",
      }),
  })
  .openapi({ required: [] })
  .openapi('KeypadInputPlan')

