const OpenAIReasonerSkillSchema = z
  .object({
    name: z
      .string()
      .regex(/\/^[a-z][a-z0-9_-]*$\//)
      .max(64)
      .openapi({ description: 'Unique name within this assistant.' }),
    description: z
      .string()
      .regex(/\/\S\//)
      .max(1024)
      .openapi({
        description:
          'Explain when the reasoner should load this skill. Always visible in its catalog.',
      }),
    content: z
      .string()
      .regex(/\/\S\//)
      .max(32000)
      .openapi({ description: 'Full skill instructions, loaded only while this skill is active.' }),
    tools: z
      .array(
        z.xor([
          CreateFunctionToolDTOSchema,
          CreateApiRequestToolDTOSchema,
          CreateMcpToolDTOSchema,
          CreateEndCallToolDTOSchema,
          CreateDtmfToolDTOSchema,
          CreateTransferCallToolDTOSchema,
        ]),
      )
      .max(20)
      .exactOptional()
      .openapi({
        description: 'Tools available only after loading this skill. Can be combined with toolIds.',
      }),
    toolIds: z
      .array(z.uuid())
      .max(20)
      .exactOptional()
      .openapi({
        description: 'Existing organization-owned tools available only after loading this skill.',
      }),
  })
  .openapi({ required: ['name', 'description', 'content'] })
  .openapi('OpenAIReasonerSkill')

