const SayHookActionSchema: z.ZodType<SayHookActionType> = z
  .object({
    type: z.literal('say').openapi({ description: 'This is the type of action - must be "say"' }),
    exact: z
      .xor([z.string(), z.array(z.string())])
      .exactOptional()
      .openapi({
        description:
          'This is the exact message to say. When a string array is provided, one is randomly selected.',
        examples: [
          'Are you still there?',
          ["I didn't catch that.", 'Could you repeat that?', 'Are you still there?'],
        ],
      }),
    prompt: z
      .xor([
        z.string().openapi({ title: 'String' }),
        z
          .array(
            z.xor([
              SystemMessageSchema.openapi({ title: 'SystemMessage' }),
              UserMessageSchema.openapi({ title: 'UserMessage' }),
              AssistantMessageSchema.openapi({ title: 'AssistantMessage' }),
              ToolMessageSchema.openapi({ title: 'ToolMessage' }),
              DeveloperMessageSchema.openapi({ title: 'DeveloperMessage' }),
            ]),
          )
          .openapi({ title: 'MessageArray' }),
      ])
      .exactOptional()
      .openapi({
        description:
          'This is the prompt for the assistant to generate a response based on existing conversation.\nCan be a string or an array of chat messages.',
        examples: [
          "Ask the user if they're still in the call",
          [
            {
              role: 'system',
              content:
                'You are a helpful assistant, and would like to know if the user is still in the call based on the conversation history in {{transcript}}',
            },
          ],
        ],
      }),
  })
  .openapi({ required: ['type'] })
  .openapi('SayHookAction')

