const BotMessageSchema = z
  .object({
    role: z.string().openapi({ description: 'The role of the bot in the conversation.' }),
    message: z.string().openapi({ description: 'The message content from the bot.' }),
    time: z.number().openapi({ description: 'The timestamp when the message was sent.' }),
    endTime: z.number().openapi({ description: 'The timestamp when the message ended.' }),
    secondsFromStart: z
      .number()
      .openapi({ description: 'The number of seconds from the start of the conversation.' }),
    source: z.string().exactOptional().openapi({ description: 'The source of the message.' }),
    duration: z
      .number()
      .exactOptional()
      .openapi({ description: 'The duration of the message in seconds.' }),
    assistantName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The name of the assistant that produced this message. In a squad or\nhandoff call this is the specific sub-agent active when the message was\nspoken, letting the transcript label each message by speaker.',
      }),
    assistantId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID of the assistant that produced this message. Stable reference for\nthe assistant named in `assistantName`.',
      }),
  })
  .openapi({ required: ['role', 'message', 'time', 'endTime', 'secondsFromStart'] })
  .openapi('BotMessage')

const ToolCallMessageSchema = z
  .object({
    role: z.string().openapi({ description: 'The role of the tool call in the conversation.' }),
    toolCalls: z
      .array(z.object({}))
      .openapi({ description: 'The list of tool calls made during the conversation.' }),
    message: z.string().openapi({ description: 'The message content for the tool call.' }),
    time: z.number().openapi({ description: 'The timestamp when the message was sent.' }),
    secondsFromStart: z
      .number()
      .openapi({ description: 'The number of seconds from the start of the conversation.' }),
  })
  .openapi({ required: ['role', 'toolCalls', 'message', 'time', 'secondsFromStart'] })
  .openapi('ToolCallMessage')

const ToolCallResultMessageWarningSchema = z
  .object({
    type: z
      .literal('oversized-tool-response')
      .openapi({
        description:
          "The kind of warning. Currently:\n- `oversized-tool-response`: the tool's serialized response exceeded the\n  recommended size and is likely to bloat the model context, increasing\n  latency and risking truncation of earlier instructions.",
      }),
    tokenCount: z
      .number()
      .openapi({ description: 'The estimated number of tokens in the serialized tool response.' }),
    threshold: z
      .number()
      .openapi({ description: 'The threshold (in tokens) above which the warning is raised.' }),
  })
  .openapi({ required: ['type', 'tokenCount', 'threshold'] })
  .openapi('ToolCallResultMessageWarning')

const ToolCallResultMessageSchema = z
  .object({
    role: z
      .string()
      .openapi({ description: 'The role of the tool call result in the conversation.' }),
    toolCallId: z.string().openapi({ description: 'The ID of the tool call.' }),
    name: z.string().openapi({ description: 'The name of the tool that returned the result.' }),
    result: z.string().openapi({ description: 'The result of the tool call in JSON format.' }),
    time: z.number().openapi({ description: 'The timestamp when the message was sent.' }),
    secondsFromStart: z
      .number()
      .openapi({ description: 'The number of seconds from the start of the conversation.' }),
    metadata: z
      .object({})
      .exactOptional()
      .openapi({ description: 'The metadata for the tool call result.' }),
    warnings: z
      .array(ToolCallResultMessageWarningSchema)
      .exactOptional()
      .openapi({
        description:
          'Warnings raised for this tool call result, e.g. when the response is\nlarger than recommended for voice AI context windows.',
      }),
  })
