const ValidateBackgroundSoundUrlDTOSchema = z
  .object({
    url: z
      .string()
      .max(1000)
      .openapi({
        description:
          'This is the background sound URL to validate. The server performs a ranged request and checks that the URL serves a live media file.',
        example: 'https://example.com/my-sound.mp3',
      }),
  })
  .openapi({ required: ['url'] })
  .openapi('ValidateBackgroundSoundUrlDTO')

const BackgroundSoundUrlValidationResultSchema = z
  .object({
    valid: z
      .boolean()
      .openapi({
        description:
          'Whether the URL currently serves a live media file. When false, calls configured with this URL silently play no background sound.',
      }),
    reason: z
      .enum([
        'invalid-url',
        'blocked-address',
        'unreachable',
        'timeout',
        'too-many-redirects',
        'http-error',
        'not-audio',
      ])
      .exactOptional()
      .openapi({ description: 'Why validation failed. Only present when valid is false.' }),
    status: z
      .number()
      .exactOptional()
      .openapi({ description: 'The HTTP status the URL returned, when a response was received.' }),
    contentType: z
      .string()
      .exactOptional()
      .openapi({ description: 'The content-type the URL returned, when a response was received.' }),
  })
  .openapi({ required: ['valid'] })
  .openapi('BackgroundSoundUrlValidationResult')

const PaginationMetaSchema = z
  .object({
    itemsPerPage: z.number(),
    totalItems: z.number(),
    currentPage: z.number(),
    totalPages: z.number().exactOptional(),
    hasNextPage: z.boolean().exactOptional(),
    nextCursor: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Opaque cursor for the next page under keyset pagination (PRO-3163). Pass it\nback as the `cursor` query param to fetch the next page without an OFFSET\nscan. Present only when a further page likely exists.',
      }),
    sortOrder: z.enum(['ASC', 'DESC']).exactOptional(),
    itemsBeyondRetention: z.boolean().exactOptional(),
    createdAtLe: z.iso.datetime({ offset: true }).exactOptional(),
    createdAtGe: z.iso.datetime({ offset: true }).exactOptional(),
  })
  .openapi({ required: ['itemsPerPage', 'totalItems', 'currentPage'] })
  .openapi('PaginationMeta')

const AssistantPaginatedResponseSchema = z
  .object({ results: z.array(AssistantSchema), metadata: PaginationMetaSchema })
  .openapi({ required: ['results', 'metadata'] })
  .openapi('AssistantPaginatedResponse')

