const SquadSchema = z
  .object({
    latestVersion: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'This is the latest version label (e.g. `v3`) of the squad in the version\nhistory. `null` while the org is not yet onboarded to versioning, or for\nsquads that have not yet been published under it.',
      }),
    modelDeprecations: z
      .array(ModelDeprecationNoticeSchema)
      .exactOptional()
      .openapi({
        description:
          'Read-only. Present only when a model this configuration uses is deprecated or retired in Vapi\'s model deprecation registry, judged on the day of the response. Each entry names the slot (for example `model` or `model.fallbackModels[1]`), provider, stored model, and deprecation and retirement dates as `YYYY-MM-DD` in UTC. `replacementStatus` is `available` with a `replacementModel` when a replacement can be recommended, or `manual-action-required` with no replacement model when eligibility is unknown or no eligible replacement exists. `manual-action-required` can be transient when compliance context is unavailable; re-fetch before acting. HIPAA-required configurations, sparse drafts, and squads with unresolved assistant references currently require manual action. HIPAA requirements include the organization and assistant settings, including HIPAA with data retention. Recommendations reflect the response-time decision; they do not confirm a swap or authorize future execution. Examples: an available recommendation includes `{"replacementStatus":"available","replacementModel":"gpt-5"}`; a blocked recommendation includes `{"replacementStatus":"manual-action-required"}`. Ignored if sent back in a create or update request.',
      }),
    name: z.string().exactOptional().openapi({ description: 'This is the name of the squad.' }),
    members: z
      .array(SquadMemberDTOSchema)
      .openapi({
        description:
          'This is the list of assistants that make up the squad.\n\nThe call will start with the first assistant in the list.',
      }),
    membersOverrides: AssistantOverridesSchema.exactOptional().openapi({
      description:
        "This can be used to override all the assistants' settings and provide values for their template variables.\n\nBoth `membersOverrides` and `members[n].assistantOverrides` can be used together. First, `members[n].assistantOverrides` is applied. Then, `membersOverrides` is applied as a global override.",
    }),
    id: z.string().openapi({ description: 'This is the unique identifier for the squad.' }),
    orgId: z
      .string()
      .openapi({
        description: 'This is the unique identifier for the org that this squad belongs to.',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'This is the ISO 8601 date-time string of when the squad was created.',
      }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'This is the ISO 8601 date-time string of when the squad was last updated.',
      }),
  })
  .openapi({ required: ['members', 'id', 'orgId', 'createdAt', 'updatedAt'] })
  .openapi('Squad')

const SquadVersionSchema = z
  .object({
    versionName: z
      .string()
      .max(80)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Optional human-readable label for this version. Set when the version is published.',
      }),
    versionDescription: z
      .string()
      .max(500)
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Optional description for this version. Set when the version is published.',
      }),
    id: z.uuid().openapi({ description: 'This is the unique identifier for the version row.' }),
    orgId: z
      .uuid()
      .openapi({
        description: 'This is the unique identifier for the org that owns this version.',
      }),
    squadId: z
      .uuid()
      .openapi({
        description:
          'This is the unique identifier for the squad this version was snapshotted from.',
      }),
    version: z
      .string()
      .openapi({
        description:
          'This is the public monotonic version label, e.g. "v1".\nSystem-owned and incremented per squad; never user-supplied.',
        example: 'v1',
      }),
    configHash: z
      .string()
      .openapi({
        description: 'This is the SHA-256 hex of the snapshotted content used for no-op detection.',
      }),
    parentVersion: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'This is the prior version label (vN-1). Null on v1 or for branch roots.',
      }),
    restoredFromVersion: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The version this version was restored from. Null when it was not restored.',
      }),
    createdBy: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'This is the actor that wrote this version. Email when created via JWT; null\nwhen created via API key, and null for a baseline version authored by nobody.',
      }),
    deletedAt: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({ description: 'This is the soft-delete timestamp. Null when active.' }),
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'This is the ISO 8601 date-time string of when the version was created.',
      }),
    name: z.string().exactOptional().openapi({ description: 'This is the name of the squad.' }),
    members: z
      .array(SquadMemberDTOSchema)
      .openapi({
        description:
          'This is the list of assistants that make up the squad.\n\nThe call will start with the first assistant in the list.',
      }),
    membersOverrides: AssistantOverridesSchema.exactOptional().openapi({
      description:
        "This can be used to override all the assistants' settings and provide values for their template variables.\n\nBoth `membersOverrides` and `members[n].assistantOverrides` can be used together. First, `members[n].assistantOverrides` is applied. Then, `membersOverrides` is applied as a global override.",
    }),
  })
  .openapi({
    required: ['id', 'orgId', 'squadId', 'version', 'configHash', 'createdAt', 'members'],
  })
  .openapi('SquadVersion')

const SquadVersionPaginatedMetadataSchema = z
  .object({
    nextCursor: z.string().nullable().exactOptional(),
    hasNextPage: z.boolean(),
    limit: z.number(),
  })
