const AnalysisCostSchema = z
  .object({
    type: z
      .literal('analysis')
      .openapi({ description: "This is the type of cost, always 'analysis' for this class." }),
    analysisType: z
      .enum(['summary', 'structuredData', 'successEvaluation', 'structuredOutput'])
      .openapi({ description: 'This is the type of analysis performed.' }),
    model: z
      .object({})
      .openapi({ description: 'This is the model that was used to perform the analysis.' }),
    promptTokens: z
      .number()
      .openapi({ description: 'This is the number of prompt tokens used in the analysis.' }),
    completionTokens: z
      .number()
      .openapi({
        description: 'This is the number of completion tokens generated in the analysis.',
      }),
    cachedPromptTokens: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'This is the number of cached prompt tokens used in the analysis. This is only applicable to certain providers (e.g., OpenAI, Azure OpenAI) that support prompt caching. Cached tokens are billed at a discounted rate.',
      }),
    reasoningTokens: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'This is the number of reasoning tokens generated in the analysis, reported only by reasoning models (e.g., GPT-5) on providers that report them. This is a subset of `completionTokens`, not an addition to it: reasoning tokens are already billed at the output-token rate, so this is for visibility only and does not affect `cost`.',
      }),
    structuredOutputBreakdown: z
      .array(StructuredOutputCostBreakdownSchema)
      .exactOptional()
      .openapi({
        description:
          "This is the per-structured-output breakdown of this cost. The `cost`, `promptTokens`, `completionTokens` and `cachedPromptTokens` above are the sums of these rows.\n\nThis is only set when `analysisType` is `structuredOutput`, and it is omitted entirely rather than partially populated, so when it is present the rows always reconcile to the totals above.\n\nA structured output that was skipped, or that extracts via regex, makes no LLM call and so has no row here — this is not a complete list of the call's configured structured outputs. There is one row per evaluation, so a `structuredOutputId` can appear more than once if it was evaluated more than once; sum the rows rather than indexing them by id.",
      }),
    cost: z.number().openapi({ description: 'This is the cost of the component in USD.' }),
  })
  .openapi({
    required: ['type', 'analysisType', 'model', 'promptTokens', 'completionTokens', 'cost'],
  })
  .openapi('AnalysisCost')

