const VapiWebCallTransportSchema = z
  .object({
    conversationType: z
      .literal('voice')
      .default('voice')
      .exactOptional()
      .openapi({ description: 'This is the conversation type of the call (ie, voice or chat).' }),
    provider: z.literal('daily').openapi({ description: 'Vapi web call transport provider' }),
    roomDeleteOnUserLeaveEnabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'This determines whether the daily room will be deleted and all participants will be kicked once the user leaves the room.\nIf set to `false`, the room will be kept alive even after the user leaves, allowing clients to reconnect to the same room.\nIf set to `true`, the room will be deleted and reconnection will not be allowed.\n\nDefaults to `true`.',
        example: true,
      }),
    callToken: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "This is the meeting token the web client should join the call with.\nWhen video recording is enabled, joining with this token starts the cloud\nrecording automatically server-side, which is more reliable than the\nclient starting it after joining. Set by the server; only present when\nvideo recording is enabled.\n\nWith `videoRecordingStartMode: 'server'`, joining with the token doesn't\nstart the recording: Vapi starts it once the user joins, and the client\nmust not start it either.",
      }),
    callUrl: z
      .string()
      .exactOptional()
      .openapi({ description: 'This is the URL of the web call.' }),
    callSipUri: z
      .string()
      .exactOptional()
      .openapi({ description: 'This is the SIP URI of the web call.' }),
  })
  .openapi({ required: ['provider'] })
  .openapi('VapiWebCallTransport')

