const PhoneNumberCallRingingHookFilterSchema = z
  .object({
    type: z
      .literal('startsWith')
      .openapi({
        description:
          'This is the type of filter - matches when the specified field starts with any of the given prefixes',
      }),
    key: z
      .literal('number')
      .openapi({
        description:
          'The field to check. Currently only "number" (the caller\'s phone number) is supported.',
      }),
    startsWith: z
      .array(z.string().max(20))
      .openapi({
        description:
          'Array of prefixes to match. Do not include the + prefix. Inbound calls from numbers starting with any of these prefixes will trigger the hook actions.',
        example: ['91', '86', '7'],
      }),
  })
  .openapi({ required: ['type', 'key', 'startsWith'] })
  .openapi('PhoneNumberCallRingingHookFilter')

const TransferPhoneNumberHookActionSchema = z
  .object({
    type: z
      .literal('transfer')
      .openapi({ description: 'This is the type of action - must be "transfer"' }),
    destination: z
      .xor([
        TransferDestinationNumberSchema.openapi({ title: 'NumberTransferDestination' }),
        TransferDestinationSipSchema.openapi({ title: 'SipTransferDestination' }),
      ])
      .exactOptional()
      .openapi({
        description:
          'This is the destination details for the transfer - can be a phone number or SIP URI',
      }),
  })
  .openapi({ required: ['type'] })
  .openapi('TransferPhoneNumberHookAction')

const SayPhoneNumberHookActionSchema = z
  .object({
    type: z.literal('say').openapi({ description: 'This is the type of action - must be "say"' }),
    exact: z.string().max(4000).openapi({ description: 'This is the message to say' }),
  })
  .openapi({ required: ['type', 'exact'] })
  .openapi('SayPhoneNumberHookAction')

const PhoneNumberHookCallRingingSchema = z
  .object({
    on: z
      .literal('call.ringing')
      .openapi({ description: 'This is the event to trigger the hook on' }),
    filters: z
      .array(PhoneNumberCallRingingHookFilterSchema)
      .exactOptional()
      .openapi({
        description:
          'Optional filters to decide when to trigger the hook. Currently supports filtering by caller country code.',
      }),
    do: z
      .array(
        z.xor([
          TransferPhoneNumberHookActionSchema.openapi({ title: 'TransferPhoneNumberHookAction' }),
          SayPhoneNumberHookActionSchema.openapi({ title: 'SayPhoneNumberHookAction' }),
        ]),
      )
      .openapi({
        description: 'Only the first action will be executed. Additional actions will be ignored.',
      }),
  })
  .openapi({ required: ['on', 'do'] })
  .openapi('PhoneNumberHookCallRinging')

const PhoneNumberCallEndingHookFilterSchema = z
  .object({
    type: z
      .literal('oneOf')
      .openapi({ description: 'This is the type of filter - currently only "oneOf" is supported' }),
    key: z
      .literal('call.endedReason')
      .openapi({
        description:
          'This is the key to filter on - only "call.endedReason" is allowed for phone number call ending hooks',
      }),
    oneOf: z
      .union([
        z.literal('assistant-request-failed'),
        z.literal('assistant-request-returned-error'),
        z.literal('assistant-request-returned-unspeakable-error'),
        z.literal('assistant-request-returned-invalid-assistant'),
        z.literal('assistant-request-returned-no-assistant'),
        z.literal('assistant-request-returned-forwarding-phone-number'),
      ])
      .openapi({
        description:
          'This is the array of assistant-request related ended reasons to match against',
      }),
  })
  .openapi({ required: ['type', 'key', 'oneOf'] })
  .openapi('PhoneNumberCallEndingHookFilter')

const PhoneNumberHookCallEndingSchema = z
  .object({
    on: z
      .literal('call.ending')
      .openapi({ description: 'This is the event to trigger the hook on' }),
    filters: z
      .array(PhoneNumberCallEndingHookFilterSchema)
      .exactOptional()
      .openapi({
        description:
          'Optional filters to decide when to trigger - restricted to assistant-request related ended reasons',
      }),
    do: z
      .xor([
        TransferPhoneNumberHookActionSchema.openapi({ title: 'TransferPhoneNumberHookAction' }),
        SayPhoneNumberHookActionSchema.openapi({ title: 'SayPhoneNumberHookAction' }),
      ])
      .exactOptional()
      .openapi({ description: 'This is the action to perform when the hook triggers' }),
  })
  .openapi({ required: ['on'] })
  .openapi('PhoneNumberHookCallEnding')

const TransientTwilioPhoneNumberSchema = z
  .object({
    fallbackDestination: z
      .xor([
        TransferDestinationNumberSchema.openapi({ title: 'NumberTransferDestination' }),
        TransferDestinationSipSchema.openapi({ title: 'SipTransferDestination' }),
      ])
      .exactOptional()
      .openapi({
        description:
          'This is the fallback destination an inbound call will be transferred to if:\n1. `assistantId` is not set\n2. `squadId` is not set\n3. and, `assistant-request` message to the `serverUrl` fails\n\nIf this is not set and above conditions are met, the inbound call is hung up with an error message.',
      }),
    hooks: z
      .array(
        z.xor([
          PhoneNumberHookCallRingingSchema.openapi({ title: 'PhoneNumberHookCallRinging' }),
          PhoneNumberHookCallEndingSchema.openapi({ title: 'PhoneNumberHookCallEnding' }),
        ]),
      )
      .exactOptional()
      .openapi({
        description: 'This is the hooks that will be used for incoming calls to this phone number.',
      }),
    smsEnabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Controls whether Vapi sets the messaging webhook URL on the Twilio number during import.\n\nIf set to `false`, Vapi will not update the Twilio messaging URL, leaving it as is.\nIf `true` or omitted (default), Vapi will configure both the voice and messaging URLs.\n\n@default true',
      }),
    name: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({
        description: 'This is the name of the phone number. This is just for your own reference.',
      }),
    assistantId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the assistant that will be used for incoming calls to this phone number.\n\nIf neither `assistantId`, `squadId` nor `workflowId` is set, `assistant-request` will be sent to your Server URL. Check `ServerMessage` and `ServerMessageResponse` for the shape of the message and response that is expected.',
      }),
    workflowId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the workflow that will be used for incoming calls to this phone number.\n\nIf neither `assistantId`, `squadId`, nor `workflowId` is set, `assistant-request` will be sent to your Server URL. Check `ServerMessage` and `ServerMessageResponse` for the shape of the message and response that is expected.',
      }),
    squadId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the squad that will be used for incoming calls to this phone number.\n\nIf neither `assistantId`, `squadId`, nor `workflowId` is set, `assistant-request` will be sent to your Server URL. Check `ServerMessage` and `ServerMessageResponse` for the shape of the message and response that is expected.',
      }),
    server: ServerSchema.exactOptional().openapi({
      description:
        'This is where Vapi will send webhooks. You can find all webhooks available along with their shape in ServerMessage schema.\n\nThe order of precedence is:\n\n1. assistant.server\n2. phoneNumber.server\n3. org.server',
    }),
    twilioPhoneNumber: z
      .string()
      .openapi({
        description: 'These are the digits of the phone number you own on your Twilio.',
        deprecated: true,
      }),
    twilioAccountSid: z
      .string()
      .openapi({
        description:
          'This is your Twilio Account SID that will be used to handle this phone number.',
      }),
  })
  .openapi({ required: ['twilioPhoneNumber', 'twilioAccountSid'] })
  .openapi('TransientTwilioPhoneNumber')

