const RecordingConsentSchema = z
  .object({
    type: z
      .enum(['stay-on-line', 'verbal'])
      .openapi({ description: 'This is the type of recording consent.' }),
    grantedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'This is the date and time the recording consent was granted.\nIf not specified, it means the recording consent was not granted.',
      }),
  })
  .openapi({ required: ['type'] })
  .openapi('RecordingConsent')

const ComplianceSchema = z
  .object({
    recordingConsent: RecordingConsentSchema.exactOptional().openapi({
      description:
        'This is the recording consent of the call. Configure in `assistant.compliancePlan.recordingConsentPlan`.',
    }),
  })
  .openapi({ required: [] })
  .openapi('Compliance')

const WorkflowOverridesSchema = z
  .object({
    variableValues: z
      .object({})
      .exactOptional()
      .openapi({
        description:
          'These are values that will be used to replace the template variables in the workflow messages and other text-based fields.\nThis uses LiquidJS syntax. https://liquidjs.com/tutorials/intro-to-liquid.html\n\nSo for example, `{{ name }}` will be replaced with the value of `name` in `variableValues`.\n`{{"now" | date: "%b %d, %Y, %I:%M %p", "America/New_York"}}` will be replaced with the current date and time in New York.\n Some VAPI reserved defaults:\n - *customer* - the customer object',
      }),
  })
  .openapi({ required: [] })
  .openapi('WorkflowOverrides')

const CreateCustomerDTOSchema = z
  .object({
    numberE164CheckEnabled: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'This is the flag to toggle the E164 check for the `number` field. This is an advanced property which should be used if you know your use case requires it.\n\nUse cases:\n- `false`: To allow non-E164 numbers like `+001234567890`, `1234`, or `abc`. This is useful for dialing out to non-E164 numbers on your SIP trunks.\n- `true` (default): To allow only E164 numbers like `+14155551234`. This is standard for PSTN calls.\n\nIf `false`, the `number` is still required to only contain alphanumeric characters (regex: `/^\\+?[a-zA-Z0-9]+$/`).\n\n@default true (E164 check is enabled)',
      }),
    extension: z
      .string()
      .max(10)
      .exactOptional()
      .openapi({
        description: 'This is the extension that will be dialed after the call is answered.',
        example: null,
      }),
    assistantOverrides: AssistantOverridesSchema.exactOptional().openapi({
      description:
        "These are the overrides for the assistant's settings and template variables specific to this customer.\nThis allows customization of the assistant's behavior for individual customers in batch calls.",
    }),
    squadOverrides: AssistantOverridesSchema.exactOptional().openapi({
      description:
        'These are the overrides applied when the call targets a `squadId`. Mirrors\nthe call-level `squadOverrides` — use this instead of `assistantOverrides`\nwhen the campaign or call is squad-based.',
    }),
    number: z
      .string()
      .min(3)
      .max(40)
      .exactOptional()
      .openapi({ description: 'This is the number of the customer.' }),
    sipUri: z
      .string()
      .exactOptional()
      .openapi({ description: 'This is the SIP URI of the customer.' }),
    name: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({
        description:
          'This is the name of the customer. This is just for your own reference.\n\nFor SIP inbound calls, this is extracted from the `From` SIP header with format `"Display Name" <sip:username@domain>`.',
      }),
    email: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({ description: 'This is the email of the customer.' }),
    externalId: z
      .string()
      .max(40)
      .exactOptional()
      .openapi({ description: 'This is the external ID of the customer.' }),
  })
  .openapi({ required: [] })
  .openapi('CreateCustomerDTO')

