const CallBatchErrorSchema = z
  .object({ customer: CreateCustomerDTOSchema, error: z.string() })
  .openapi({ required: ['customer', 'error'] })
  .openapi('CallBatchError')

const CallBatchResponseSchema = z
  .object({
    subscriptionLimits: SubscriptionLimitsSchema.exactOptional().openapi({
      description: 'Subscription limits at the end of this batch',
    }),
    results: z
      .array(CallSchema)
      .openapi({ description: 'This is the list of calls that were created.' }),
    errors: z
      .array(CallBatchErrorSchema)
      .openapi({ description: 'This is the list of calls that failed to be created.' }),
  })
  .openapi({ required: ['results', 'errors'] })
  .openapi('CallBatchResponse')

const AssistantSpeechWordAlignmentTimingSchema = z
  .object({
    type: z
      .literal('word-alignment')
      .openapi({
        description: 'Discriminator for exact per-word timing (e.g. ElevenLabs alignment).',
      }),
    words: z
      .array(z.string())
      .openapi({ description: 'The individual words in this audio segment.' }),
    wordsStartTimesMs: z
      .array(z.number())
      .openapi({ description: 'Start time in milliseconds for each word (parallel to `words`).' }),
    wordsEndTimesMs: z
      .array(z.number())
      .openapi({ description: 'End time in milliseconds for each word (parallel to `words`).' }),
  })
  .openapi({ required: ['type', 'words', 'wordsStartTimesMs', 'wordsEndTimesMs'] })
  .openapi('AssistantSpeechWordAlignmentTiming')

const AssistantSpeechWordTimestampSchema = z
  .object({
    word: z
      .string()
      .openapi({ description: 'The full word text (syllables aggregated into complete words).' }),
    startMs: z
      .number()
      .openapi({ description: 'Start time in milliseconds relative to the segment start.' }),
    endMs: z
      .number()
      .openapi({ description: 'End time in milliseconds relative to the segment start.' }),
  })
  .openapi({ required: ['word', 'startMs', 'endMs'] })
  .openapi('AssistantSpeechWordTimestamp')

const AssistantSpeechWordProgressTimingSchema = z
  .object({
    type: z
      .literal('word-progress')
      .openapi({
        description: 'Discriminator for cursor-based word progress (e.g. Minimax subtitle data).',
      }),
    wordsSpoken: z.number().openapi({ description: 'Number of words spoken so far in this turn.' }),
    totalWords: z
      .number()
      .openapi({
        description:
          'Total number of words sent to the TTS provider for this turn.\n\n**Important**: this value grows across events within a single turn because\nMinimax synthesizes audio incrementally as the LLM streams tokens. Treat\nit as "best known total so far" — it will stabilize once synthesis is\ncomplete.\n\nA value of `0` is a valid sentinel meaning "not yet known". This can occur\non the very first `assistant-speech` event of a turn if audio begins\nplaying before the TTS provider has confirmed word-count data. Clients\n**must** guard against divide-by-zero when computing a progress fraction:\n\n```ts\nconst pct = totalWords > 0 ? wordsSpoken / totalWords : 0;\n```',
      }),
    segment: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The text of the latest spoken segment (sentence or clause). Use this\nfor caption display — it corresponds to the chunk just confirmed by\nthe TTS provider, unlike `text` on the parent message which carries\nthe full turn text.',
      }),
    segmentDurationMs: z
      .number()
      .exactOptional()
      .openapi({
        description:
          'Audio duration in milliseconds for the latest spoken segment. Pair\nwith `segment` to animate karaoke-style word reveals — divide the\nsegment text across this duration for approximate per-word timing.',
      }),
    words: z
      .array(AssistantSpeechWordTimestampSchema)
      .exactOptional()
      .openapi({
        description:
          'Per-word timestamps for the latest spoken segment. Available when the\nTTS provider supports word-level timing (e.g. Minimax with\nsubtitle_type: "word"). Syllables from the provider are aggregated\ninto whole words with start/end times relative to the segment start.\n\nUse these for precise karaoke-style highlighting instead of\ninterpolating from segmentDurationMs.',
      }),
  })
  .openapi({ required: ['type', 'wordsSpoken', 'totalWords'] })
  .openapi('AssistantSpeechWordProgressTiming')

