const StructuredOutputRunResultSchema = z
  .object({
    name: z
      .string()
      .openapi({
        description: 'This is the name of the structured output that produced this value.',
      }),
    result: z
      .xor([z.string(), z.number(), z.boolean(), z.object({}), z.array(z.any())])
      .nullable()
      .openapi({
        description: "This is the extracted value, shaped by the structured output's schema.",
      }),
    compliancePlan: ComplianceOverrideSchema.exactOptional(),
  })
  .openapi({ required: ['name', 'result'] })
  .openapi('StructuredOutputRunResult')

const StructuredOutputRunPreviewResponseSchema = z
  .object({
    skipped: z
      .record(z.string(), SkippedStructuredOutputSchema)
      .exactOptional()
      .openapi({
        description:
          'These are the structured outputs whose conditions gated them, keyed by\nstructured output id. Absent when nothing was skipped. An entry here means\nno extraction ran and no cost was incurred for that output.',
      }),
  })
  .openapi({ required: [] })
  .openapi('StructuredOutputRunPreviewResponse')

const StructuredOutputRerunResponseSchema = z
  .object({
    workflowId: z
      .string()
      .exactOptional()
      .openapi({ description: 'This is the id of the workflow processing the rerun.' }),
    message: z.string(),
  })
  .openapi({ required: ['message'] })
  .openapi('StructuredOutputRerunResponse')

const StructuredOutputSchema = z
  .object({
    type: z
      .enum(['ai', 'regex'])
      .exactOptional()
      .openapi({
        description:
          "This is the type of structured output.\n\n- 'ai': Uses an LLM to extract structured data from the conversation (default).\n- 'regex': Uses a regex pattern to extract data from the transcript without an LLM.",
      }),
    regex: z
      .string()
      .min(1)
      .max(1000)
      .exactOptional()
      .openapi({
        description:
          "This is the regex pattern to match against the transcript.\n\nSimulation evaluations use a canonical transcript built from recorded messages:\nUser: and AI: dialogue, AI: tool_calls: JSON name/arguments records, and\nAI: tool_call_results: JSON results. System messages are excluded. These\nfixed labels apply even when custom artifact transcript labels are configured.\nTool payloads participate in first-match and all-match extraction in event order.\nAn empty message array falls back to the supplied transcript verbatim.\nProduction-call extraction and call preview use their existing transcripts,\nso previewing the same output on a simulation's call can return a different result.\n\nOnly used when type is 'regex'. Supports both raw patterns (e.g. '\\d+') and\nregex literal format (e.g. '/\\d+/gi'). Uses RE2 syntax for safety.\n\nThe result depends on the schema type:\n- boolean: true if the pattern matches, false otherwise\n- string: the first match or first capture group\n- number/integer: the first match parsed as a number\n- array: all matches",
      }),
    model: z
      .xor([
        WorkflowOpenAIModelSchema.openapi({ title: 'WorkflowOpenAIModel' }),
        WorkflowAnthropicModelSchema.openapi({ title: 'WorkflowAnthropicModel' }),
        WorkflowAnthropicBedrockModelSchema.openapi({ title: 'WorkflowAnthropicBedrockModel' }),
        WorkflowGoogleModelSchema.openapi({ title: 'WorkflowGoogleModel' }),
        WorkflowCustomModelSchema.openapi({ title: 'WorkflowCustomModel' }),
      ])
      .exactOptional()
      .openapi({
        description:
          "This is the model that will be used to extract the structured output.\n\nTo provide your own custom system and user prompts for structured output extraction, populate the messages array with your system and user messages. You can specify liquid templating in your system and user messages.\nFor text extraction, you must reference 'transcript', 'messages', or 'messagesWithConfidence' with the `{{}}` syntax to access the conversation history.\nIn structured outputs, `{{messages}}` includes conversation text and tool calls/results but omits caller transcription-confidence fields. Text extraction can use `{{messagesWithConfidence}}` when the output needs the original message history with transcription confidence. These variables also apply in structured-output schema descriptions. Audio-targeted (`messages-with-audio`) extraction ignores custom messages. Stored call artifacts and API messages retain their confidence data.\nBetween the system or user messages, you must reference a variation of the structured output with the `{{}}` syntax to access the structured output definition.\ni.e.:\n`{{structuredOutput}}`\n`{{structuredOutput.name}}`\n`{{structuredOutput.description}}`\n`{{structuredOutput.schema}}`\n\nIf model is not specified, GPT-4.1 will be used by default for extraction, utilizing default system and user prompts.\nIf messages or required fields are not specified, the default system and user prompts will be used.",
      }),
    compliancePlan: ComplianceOverrideSchema.exactOptional().openapi({
      description:
        'Compliance configuration for this output. Only enable overrides if no sensitive data will be stored.',
      example: { forceStoreOnHipaaEnabled: false },
    }),
    conditions: z
      .array(
        z.xor([
          MinMessagesConditionSchema.openapi({ title: 'MinMessagesCondition' }),
          MinCallDurationConditionSchema.openapi({ title: 'MinCallDurationCondition' }),
          EndedReasonConditionSchema.openapi({ title: 'EndedReasonCondition' }),
        ]),
      )
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'These are the conditions that gate the execution of this structured output. Every condition must pass for the structured output to run (AND semantics). When omitted or empty, no user-defined conditions gate this output. Send null to clear a previously saved gate.',
        example: [
          { type: 'minMessages', count: 4 },
          { type: 'minCallDuration', seconds: 10 },
        ],
      }),
    id: z
      .string()
      .openapi({ description: 'This is the unique identifier for the structured output.' }),
    orgId: z
      .string()
      .openapi({
        description:
          'This is the unique identifier for the org that this structured output belongs to.',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'This is the ISO 8601 date-time string of when the structured output was created.',
      }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'This is the ISO 8601 date-time string of when the structured output was last updated.',
      }),
    name: z
      .string()
      .min(1)
      .max(40)
      .openapi({ description: 'This is the name of the structured output.' }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the description of what the structured output extracts.\n\nUse this to provide context about what data will be extracted and how it will be used.',
      }),
    assistantIds: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          "These are the assistant IDs that this structured output is linked to.\n\nWhen linked to assistants, this structured output will be available for extraction during those assistant's calls.",
      }),
    workflowIds: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          "These are the workflow IDs that this structured output is linked to.\n\nWhen linked to workflows, this structured output will be available for extraction during those workflow's execution.",
      }),
    schema: JsonSchemaSchema.openapi({
      description:
        'This is the JSON Schema definition for the structured output.\n\nDefines the structure and validation rules for the data that will be extracted. Supports all JSON Schema features including:\n- Objects and nested properties\n- Arrays and array validation\n- String, number, boolean, and null types\n- Enums and const values\n- Validation constraints (min/max, patterns, etc.)\n- Composition with allOf, anyOf, oneOf',
    }),
  })
  .openapi({ required: ['id', 'orgId', 'createdAt', 'updatedAt', 'name', 'schema'] })
  .openapi('StructuredOutput')

const StructuredOutputPaginatedResponseSchema = z
  .object({ results: z.array(StructuredOutputSchema), metadata: PaginationMetaSchema })
  .openapi({ required: ['results', 'metadata'] })
  .openapi('StructuredOutputPaginatedResponse')

