const StructuredOutputRunDTOSchema = z
  .object({
    previewEnabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'This is the preview flag for the re-run. If true, the re-run will be executed and the response will be returned immediately and the call artifact will NOT be updated.\nIf false (default), the re-run will be executed and the response will be updated in the call artifact.',
      }),
    structuredOutputId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the ID of the structured output that will be run. This must be provided unless a transient structured output is provided.\nWhen the re-run is executed, only the value of this structured output will be replaced with the new value, or added if not present.',
      }),
    structuredOutput: CreateStructuredOutputDTOSchema.exactOptional().openapi({
      description:
        'This is the transient structured output that will be run. This must be provided if a structured output ID is not provided.\nWhen the re-run is executed, the structured output value will be added to the existing artifact.',
    }),
    callIds: z
      .array(z.string())
      .openapi({
        description:
          'This is the array of callIds that will be updated with the new structured output value. If preview is true, this array must be provided and contain exactly 1 callId.\nIf preview is false, up to 100 callIds may be provided.',
      }),
  })
  .openapi({ required: ['callIds'] })
  .openapi('StructuredOutputRunDTO')

