const EvaluationPlanItemSchema = z
  .object({
    structuredOutputId: z
      .uuid()
      .exactOptional()
      .openapi({
        description:
          'This is the ID of an existing structured output to use for evaluation.\nMutually exclusive with structuredOutput.',
      }),
    structuredOutput: CreateStructuredOutputDTOSchema.exactOptional().openapi({
      description:
        'This is an inline structured output definition for evaluation.\nMutually exclusive with structuredOutputId.\nOnly primitive schema types (string, number, integer, boolean) are allowed.',
    }),
    path: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Optional dot-notation path to a primitive leaf when evaluating an object structured output.',
        example: 'contact.auth_started',
      }),
    comparator: z
      .enum(['=', '!=', '>', '<', '>=', '<='])
      .openapi({
        description:
          "This is the comparison operator to use when evaluating the extracted value against the expected value.\nAvailable operators depend on the structured output's schema type:\n- boolean: '=', '!='\n- string: '=', '!='\n- number/integer: '=', '!=', '>', '<', '>=', '<='",
        example: '=',
      }),
    value: z
      .xor([z.number(), z.string(), z.boolean()])
      .openapi({
        description:
          "This is the expected value to compare against the extracted structured output result.\nType should match the structured output's schema type.",
      }),
    required: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'This is whether this evaluation must pass for the simulation to pass.\nDefaults to true. If false, the result is informational only.',
      }),
  })
  .openapi({ required: ['comparator', 'value'] })
  .openapi('EvaluationPlanItem')

