const BoardMetricWidgetItemSchema = z
  .object({
    type: z.enum(['failed_calls_list', 'concurrency_chart', 'average_cost_breakdown_chart']),
    position: BoardItemPositionSchema,
    size: BoardItemSizeSchema,
    insightId: z.string().exactOptional(),
    systemKey: z.string().exactOptional(),
  })
  .openapi({ required: ['type', 'position', 'size'] })
  .openapi('BoardMetricWidgetItem')

const BoardSchema = z
  .object({
    items: z
      .array(z.xor([BoardInsightItemSchema, BoardMetricWidgetItemSchema]))
      .exactOptional()
      .openapi({
        description:
          'This is the contents of the Board, which is an array of objects defining the type, contents, and position of the widgets on the Board.',
      }),
    id: z.string().openapi({ description: 'This is the unique identifier for the Board.' }),
    orgId: z
      .string()
      .openapi({
        description: 'This is the unique identifier for the org that this Board belongs to.',
      }),
    createdAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'This is the ISO 8601 date-time string of when the Board was created.',
      }),
    updatedAt: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'This is the ISO 8601 date-time string of when the Board was last updated.',
      }),
    systemKey: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Server-owned key for system-provisioned boards. User create/update DTOs do\nnot accept this field.',
      }),
    name: z.string().min(1).max(40).openapi({ description: 'This is the name of the Board.' }),
    layout: BoardLayoutSchema.openapi({ description: 'This is the layout of the Board.' }),
    timeRangeOverride: InsightTimeRangeWithStepSchema.exactOptional().openapi({
      description:
        'This is the timerange override for the board.\nBy default, individual insights have their own timerange.\nThis is a global override for the board which will be passed to all insights on the board.',
    }),
  })
  .openapi({ required: ['id', 'orgId', 'createdAt', 'updatedAt', 'name', 'layout'] })
  .openapi('Board')

