const EvalRunSchema = z
  .object({
    status: z
      .enum(['running', 'ended', 'queued'])
      .openapi({
        description:
          "This is the status of the eval run. When an eval run is created, the status is 'running'.\nWhen the eval run is completed, the status is 'ended'.",
        example: 'running',
      }),
    endedReason: z
      .enum(['mockConversation.done', 'error', 'timeout', 'cancelled', 'aborted'])
      .openapi({
        description:
          "This is the reason for the eval run to end.\nWhen the eval run is completed normally i.e end of mock conversation, the status is 'mockConversation.done'.\nWhen the eval fails due to an error like Chat error or incorrect configuration, the status is 'error'.\nWhen the eval runs for too long, due to model issues or tool call issues, the status is 'timeout'.\nWhen the eval run is cancelled by the user, the status is 'cancelled'.\nWhen the eval run is cancelled by Vapi for any reason, the status is 'aborted'.",
        example: 'mockConversation.done',
      }),
    eval: CreateEvalDTOSchema.exactOptional().openapi({
      description: 'This is the transient eval that will be run',
    }),
    target: z
      .xor([
        EvalRunTargetAssistantSchema.openapi({ title: 'EvalRunTargetAssistant' }),
        EvalRunTargetSquadSchema.openapi({ title: 'EvalRunTargetSquad' }),
      ])
      .openapi({ description: 'This is the target that will be run against the eval' }),
    id: z.string(),
    orgId: z.string(),
    createdAt: z.iso.datetime({ offset: true }),
    startedAt: z.iso.datetime({ offset: true }),
    endedAt: z.iso.datetime({ offset: true }),
    endedMessage: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This is the ended message when the eval run ended for any reason apart from mockConversation.done',
        example: 'The Assistant returned an error',
      }),
    results: z
      .array(EvalRunResultSchema)
      .openapi({
        description:
          'This is the results of the eval or suite run.\nThe array will have a single item for an eval run, and multiple items each corresponding to the an eval in a suite run in the same order as the evals in the suite.',
      }),
    cost: z
      .number()
      .openapi({ description: 'This is the cost of the eval or suite run in USD.', example: 0.01 }),
    costs: z
      .array(z.object({}))
      .openapi({
        description: 'This is the break up of costs of the eval or suite run.',
        example: '[{ type: "model", model: "gpt-4o", cost: 0.01 }]',
      }),
    type: z
      .literal('eval')
      .openapi({
        description: 'This is the type of the run.\nCurrently it is fixed to `eval`.',
        example: 'eval',
      }),
    evalId: z
      .string()
      .exactOptional()
      .openapi({
        description: 'This is the id of the eval that will be run.',
        example: '123e4567-e89b-12d3-a456-426614174000',
      }),
  })
  .openapi({
    required: [
      'status',
      'endedReason',
      'target',
      'id',
      'orgId',
      'createdAt',
      'startedAt',
      'endedAt',
      'results',
      'cost',
      'costs',
      'type',
    ],
  })
  .openapi('EvalRun')

