const GoalEvaluationCurrentCallRequestDTOSchema = z
  .object({ callId: z.uuid(), goalId: z.uuid() })
  .openapi({ required: ['callId', 'goalId'] })
  .openapi('GoalEvaluationCurrentCallRequestDTO')

const GoalEvaluationCurrentBatchRequestDTOSchema = z
  .object({
    evaluations: z
      .array(GoalEvaluationCurrentCallRequestDTOSchema)
      .min(1)
      .max(100)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'Explicit call/goal pairs. The organization comes from the authenticated caller.',
      }),
  })
  .openapi({ required: ['evaluations'] })
  .openapi('GoalEvaluationCurrentBatchRequestDTO')

const GoalEvaluationCurrentBatchResponseDTOSchema = z
  .object({
    results: z
      .array(GoalEvaluationCurrentCallResponseDTOSchema)
      .max(100)
      .openapi({
        description:
          'One entry per requested call/goal pair, in request order, including entries without a current evaluation.',
      }),
  })
  .openapi({ required: ['results'] })
  .openapi('GoalEvaluationCurrentBatchResponseDTO')

