export const getV2CampaignIdContactsRoute = createRoute({
  method: 'get',
  path: '/v2/campaign/{id}/contacts',
  tags: ['Campaigns'],
  summary: 'Get Campaign V2 Contacts',
  operationId: 'CampaignController_getCampaignV2Contacts',
  request: {
    params: z.object({
      id: z
        .uuid()
        .openapi({
          param: {
            name: 'id',
            required: true,
            in: 'path',
            description: 'The unique identifier for the resource.',
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
    query: z.object({
      status: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z.enum([
              'contact.pending',
              'contact.dispatched',
              'contact.completed',
              'contact.failed',
              'contact.skipped',
              'contact.predial-failed',
            ]),
          ),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            required: false,
            in: 'query',
            description:
              'This is the status to filter contacts by. Pass once or multiple times to\nfilter on any of the provided statuses.',
            schema: {
              type: 'array',
              items: {
                type: 'string',
                enum: [
                  'contact.pending',
                  'contact.dispatched',
                  'contact.completed',
                  'contact.failed',
                  'contact.skipped',
                  'contact.predial-failed',
                ],
              },
            },
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1).max(1000),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            required: false,
            in: 'query',
            description: 'This is the maximum number of contacts to return. Defaults to 50.',
            schema: { minimum: 1, maximum: 1000, type: 'number' },
          },
        }),
      sortBy: z
        .enum(['position', 'status'])
        .exactOptional()
        .openapi({
          param: {
            name: 'sortBy',
            required: false,
            in: 'query',
            description:
              "This is the column to sort by. Defaults to `position` — the order contacts\nwere uploaded, which is also dial order.\n\n`status` sorts by the enum's declaration order rather than alphabetically,\nwhich means it reads as a lifecycle: pending, dispatched, completed,\nfailed, skipped, predial-failed.\n\nOnly columns on `campaign_contact` are sortable. Call-level values such as\ncost or duration live on the call and are attached after this query, so\nsorting by them here would only reorder the current page.",
            schema: { enum: ['position', 'status'], type: 'string' },
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            required: false,
            in: 'query',
            description: 'This is the page number to return. Defaults to 1.',
            schema: { minimum: 1, type: 'number' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: CampaignContactPaginatedResponseSchema } },
    },
  },
  security: [{ bearer: [] }],
})

