export const postTrafficAllocationsRoute = createRoute({
  method: 'post',
  path: '/traffic-allocations',
  tags: ['Traffic Allocations'],
  summary: 'Create traffic allocation',
  description:
    "Creates a new traffic allocation for an assistant, replacing the one currently in effect. To start or adjust a split, send targets naming published versions (such as \"v7\") with percentages totaling 100; allocationIntent is inferred as 'explicit'. To stop splitting and send every call to the newest published version, send allocationIntent 'follow-latest' with no targets field; stopping always names its intent, so a dropped targets field can never end a split by accident.",
  operationId: 'TrafficAllocationController_create',
  request: {
    body: {
      content: { 'application/json': { schema: CreateTrafficAllocationDTOSchema } },
      required: true,
    },
  },
  responses: {
    201: { description: '', content: { 'application/json': { schema: TrafficAllocationSchema } } },
    400: {
      description:
        'Create 400s when the request carries neither targets nor an allocationIntent, when the target set breaks a shape rule (targets combined with follow-latest, an explicit allocation with no targets, duplicate target versions, percentages not totaling 100, no positive percentage), or when a target names a version that does not exist on this assistant.',
    },
    403: {
      description:
        'Traffic splitting is not enabled for your organization. The feature is in beta, rolling out to select organizations.',
    },
    404: { description: 'The source assistant does not exist.' },
    409: {
      description:
        'The provided expectedCurrentAllocationId no longer matches the allocation currently in effect (see TrafficAllocationStaleConflictResponseDTO; omitting the field never conflicts), or Vapi for CX manages the assistant (see AssistantManagedConflictResponseDTO).',
      content: {
        'application/json': {
          schema: z
            .xor([
              TrafficAllocationStaleConflictResponseDTOSchema,
              AssistantManagedConflictResponseDTOSchema,
            ])
            .openapi({
              discriminator: {
                propertyName: 'error',
                mapping: {
                  stale_allocation:
                    '#/components/schemas/TrafficAllocationStaleConflictResponseDTO',
                  assistant_managed_by_vapi_agents:
                    '#/components/schemas/AssistantManagedConflictResponseDTO',
                },
              },
            }),
        },
      },
    },
  },
  security: [{ bearer: [] }],
})

