export const getTrafficAllocationsMetricsRoute = createRoute({
  method: 'get',
  path: '/traffic-allocations/metrics',
  tags: ['Traffic Allocations'],
  summary: 'Get traffic split metrics',
  description:
    "Per-assistant-version call metrics over a time window: call counts, configured vs actual traffic share, duration, cost per minute, latency, ended reasons, a bucketed timeseries, and optional structured output aggregations. Calls with no assistant version are reported as an 'unversioned' row.",
  operationId: 'TrafficAllocationController_metricsGet',
  request: {
    query: z.object({
      assistantId: z
        .string()
        .openapi({
          param: {
            name: 'assistantId',
            required: true,
            in: 'query',
            description: 'The assistant whose per-version traffic metrics to return.',
            schema: { type: 'string' },
          },
        }),
      from: z.iso
        .datetime({ offset: true })
        .openapi({
          param: {
            name: 'from',
            required: true,
            in: 'query',
            description: 'Start of the metrics window (inclusive), ISO 8601 datetime.',
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      to: z.iso
        .datetime({ offset: true })
        .openapi({
          param: {
            name: 'to',
            required: true,
            in: 'query',
            description:
              'End of the metrics window (exclusive), ISO 8601 datetime. Must be later than from, and the window may hold at most 2000 buckets of the requested width.',
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      bucket: z
        .enum(['hour', 'day'])
        .exactOptional()
        .openapi({
          param: {
            name: 'bucket',
            required: false,
            in: 'query',
            description: "Bucket size for the timeseries. Defaults to 'day'.",
            schema: { enum: ['hour', 'day'], type: 'string' },
          },
        }),
      structuredOutputIds: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.any()).max(5),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'structuredOutputIds',
            required: false,
            in: 'query',
            description:
              'Structured output ids to aggregate per version, as an array or a comma-separated string. At most 5.',
            schema: { maxItems: 5, type: 'array' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: { 'application/json': { schema: TrafficTabMetricsDTOSchema } },
    },
    400: {
      description:
        'assistantId is missing or not a UUID, from/to are missing, malformed, or inverted, the window spans more than 2000 buckets, or structuredOutputIds has more than 5 entries or a non-UUID entry.',
    },
    403: {
      description:
        'Traffic splitting is not enabled for your organization. The feature is in beta, rolling out to select organizations.',
    },
  },
  security: [{ bearer: [] }],
})

