export const postEvalSimulationRunRoute = createRoute({
  method: 'post',
  path: '/eval/simulation/run',
  tags: ['Simulation Runs'],
  summary: 'Create Simulation Run',
  operationId: 'SimulationRunController_create',
  request: {
    headers: z.object({
      'Idempotency-Key': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Idempotency-Key',
            in: 'header',
            description:
              'Makes the request safe to retry. A retry with the same key and the same body returns the run the first request created, with `reused: true`, instead of starting another. Reusing a key with a different body returns 409. Up to 255 printable ASCII characters, scoped to your organization; a key stays bound to its run while the run exists.',
            required: false,
            schema: { type: 'string' },
          },
        }),
      'user-agent': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'user-agent',
            in: 'header',
            description: 'Identifies the client starting the simulation run',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: { 'application/json': { schema: CreateSimulationRunDTOSchema } },
      required: true,
    },
  },
  responses: {
    201: {
      description: '',
      content: { 'application/json': { schema: CreateSimulationRunResponseSchema } },
    },
    402: {
      description: 'The organization is not eligible to start this run.',
      content: { 'application/json': { schema: SimulationRunPaymentRequiredResponseSchema } },
    },
    409: {
      description:
        'The Idempotency-Key was already used with a different request body, or a concurrent request with the same key did not complete.',
    },
  },
  security: [{ bearer: [] }],
})

